CREATED = {
    'position_accuracy.py': '"""\nposition_accuracy.py - How well JPL knows a plotted position, and the hover\'s\ndistances and speeds printed to the digits that knowledge earns.\n\nThe orrery\'s body hover printed every distance to ten decimal places of an\nAU and ten figures of a kilometre, whatever JPL knows (L-401). This module\nworks out, for one body seen from one centre on one date, the error the\nnumbers carry, and formats each unit by it. Rulings:\ndocumentation/DESIGN_L401_distance_digits_rulings_20261011.md and\ndocumentation/HANDOFF_L401_distance_build1_brief_20261011.md.\n\nWHERE EACH ERROR COMES FROM (one place; the hover reads only this)\n    planet or Pluto   JPL\'s published accuracy for its orbit, the three\n                      DE430 rows in constants_new.py (Folkner et al. 2014),\n                      used as half a unit of each row\'s place\n    the Moon          its own DE430 row, "known to submeter accuracy"\n    a small body      JPL\'s own uncertainty for that date, from the same\n                      Horizons vector query that returns the position,\n                      VEC_TABLE=\'2xr\', times three (3-sigma); fetched by\n                      fetch_small_body_state() below\n    anything else     "no stated error", its own state, never a tiny\n                      invented number: a moon seen from its planet, a\n                      spacecraft, a Lagrange point, a barycentre\n    The plot\'s centre joins by the larger of the two errors (Tony,\n    2026-10-01) when the body has an error of its own; a body with none\n    keeps none, whatever the centre. A moon seen from the Sun uses its planet\'s row as a\n    floor: a lower bound, said so in words. The Sun adds nothing on\n    either side, since a planet\'s accuracy is that of its orbit about\n    the Sun; seen from a spacecraft or a barycentre it has none.\n\nHOW THE DIGITS ARE CHOSEN\n    Each unit (AU, kilometers, light time, AU/day, km/hr, km/s) is placed\n    by its own Report test (provenance-discipline 2.28, The ceiling,\n    Report): the power of ten whose half-unit is nearest the error on a\n    log scale, a tie to the coarser. A distance is never finer than whole\n    kilometers, the stated floor. A speed with a stated distance error\n    keeps the distance\'s relative precision ("Reading 1", Tony,\n    2026-10-11); a small body\'s speed uses JPL\'s three velocity\n    uncertainties combined, times three; a speed with no stated error is\n    printed to one meter per second with a plain sentence (ruled\n    2026-10-11). Never fewer than one figure; plain numbers, no\n    scientific notation.\n\nKey functions:\n    resolve_accuracy() - the error state for one body, centre and date\n    distance_speed_lines() - the hover\'s distance and speed lines, with\n        the sentence that says which kind of figure they are\n    fetch_small_body_state() - a small body\'s position with its 2xr\n        uncertainties, by a direct call to the Horizons API\n\nConsumed by: visualization_utils.format_detailed_hover_text (the static\nplot, the animation and the social export) and palomas_orrery.fetch_position;\nchecked by test_position_digits.py.\n\nRole: computation\nDomain: orrery\n\nModule created: October 12, 2026 with Anthropic\'s Claude Opus 5.5 (L-401,\nbuild 1, the body hover).\n"""\n\nimport math\nimport re\n\nfrom constants_new import (\n    KM_PER_AU,\n    LIGHT_MINUTES_PER_AU,\n    SPEED_OF_LIGHT_KM_S,\n    S_PER_HOUR,\n    S_PER_DAY,\n    DE430_TERRESTRIAL_POSITION_PLACE_KM,\n    DE430_JUPITER_SATURN_POSITION_PLACE_KM,\n    DE430_URANUS_NEPTUNE_PLUTO_POSITION_PLACE_KM,\n    DE430_MOON_POSITION_PLACE_KM,\n    VOYAGER_1_POINTING_RA_2030_ARCSEC,\n    VOYAGER_1_POINTING_DEC_2030_ARCSEC,\n    VOYAGER_2_POINTING_RA_2030_ARCSEC,\n    VOYAGER_2_POINTING_DEC_2030_ARCSEC,\n    ARCSEC_PER_DEG,\n    DEG_PER_RAD,\n)\nfrom orbital_period import report_exponent, format_by_error, _is_small_body\n\n# ============================================================================\n# THE ROWS, THE LEVEL AND THE FLOORS\n# ============================================================================\n\n# Which published row each body points at. Names, not values: the values\n# live in constants_new.py with their sources.\nPUBLISHED_ROW_NAMES = {\n    \'Mercury\': \'DE430_TERRESTRIAL_POSITION_PLACE_KM\',\n    \'Venus\': \'DE430_TERRESTRIAL_POSITION_PLACE_KM\',\n    \'Earth\': \'DE430_TERRESTRIAL_POSITION_PLACE_KM\',\n    \'Mars\': \'DE430_TERRESTRIAL_POSITION_PLACE_KM\',\n    \'Jupiter\': \'DE430_JUPITER_SATURN_POSITION_PLACE_KM\',\n    \'Saturn\': \'DE430_JUPITER_SATURN_POSITION_PLACE_KM\',\n    \'Uranus\': \'DE430_URANUS_NEPTUNE_PLUTO_POSITION_PLACE_KM\',\n    \'Neptune\': \'DE430_URANUS_NEPTUNE_PLUTO_POSITION_PLACE_KM\',\n    \'Pluto\': \'DE430_URANUS_NEPTUNE_PLUTO_POSITION_PLACE_KM\',\n}\nMOON_ROW_NAME = \'DE430_MOON_POSITION_PLACE_KM\'\n\nROW_VALUES = {\n    \'DE430_TERRESTRIAL_POSITION_PLACE_KM\': DE430_TERRESTRIAL_POSITION_PLACE_KM,\n    \'DE430_JUPITER_SATURN_POSITION_PLACE_KM\': DE430_JUPITER_SATURN_POSITION_PLACE_KM,\n    \'DE430_URANUS_NEPTUNE_PLUTO_POSITION_PLACE_KM\': DE430_URANUS_NEPTUNE_PLUTO_POSITION_PLACE_KM,\n    \'DE430_MOON_POSITION_PLACE_KM\': DE430_MOON_POSITION_PLACE_KM,\n    \'VOYAGER_1_POINTING_RA_2030_ARCSEC\': VOYAGER_1_POINTING_RA_2030_ARCSEC,\n    \'VOYAGER_1_POINTING_DEC_2030_ARCSEC\': VOYAGER_1_POINTING_DEC_2030_ARCSEC,\n    \'VOYAGER_2_POINTING_RA_2030_ARCSEC\': VOYAGER_2_POINTING_RA_2030_ARCSEC,\n    \'VOYAGER_2_POINTING_DEC_2030_ARCSEC\': VOYAGER_2_POINTING_DEC_2030_ARCSEC,\n}\n\n# Spacecraft whose own Horizons data sheet states a trajectory\n# uncertainty: the Voyagers, as a predicted pointing uncertainty seen from\n# Earth for 2030, an angle (the survey of all 26 sheets, 2026-10-12). The\n# hover converts the larger of RA and DEC at the spacecraft\'s distance from\n# Earth, and says the conversion is ours (Tony, 2026-10-12, option A).\nSPACECRAFT_SHEET_ROWS = {\n    \'Voyager 1\': (\'VOYAGER_1_POINTING_RA_2030_ARCSEC\', \'VOYAGER_1_POINTING_DEC_2030_ARCSEC\'),\n    \'Voyager 2\': (\'VOYAGER_2_POINTING_RA_2030_ARCSEC\', \'VOYAGER_2_POINTING_DEC_2030_ARCSEC\'),\n}\nSHEET_FIGURES = 4   # the sheets print four figures (the rows\' # Figures: lines)\n\n# These four are display rules, not measurements. Each is cited to the\n# ruling it comes from.\n\nHALF_UNIT = 0.5\n# Source: provenance-discipline 2.28, An Accuracy Stated in Words Is\n# Source+: Stored as the Place It Reports To -- a row stores the place its\n# Source+: words report to, and "the display uses half a unit of the\n# Source+: place" as the source\'s error.\n\nSIGMA_MULTIPLE = 3\n# Source: documentation/DESIGN_L401_distance_digits_rulings_20261011.md,\n# Source+: section 4, item 5 -- "The level is 3-sigma". Horizons\' 2xr\n# Source+: columns are 1-sigma (the vector table\'s own column notes, read\n# Source+: 2026-10-12), so every figure kept is three times that, and\n# Source+: every field name says so.\n\nDISTANCE_FLOOR_EXPONENT_KM = 0\n# Source: documentation/DESIGN_L401_distance_digits_rulings_20261011.md,\n# Source+: section 4, item 4 -- no stated error prints "to whole\n# Source+: kilometres, the website\'s floor"; never finer for any body\n# Source+: (provenance-discipline 2.28, A Computed Position Prints What\n# Source+: Its Errors Earn). The exponent of ten in kilometers.\n\nSPEED_FLOOR_EXPONENT_KM_S = -3\n# Source: documentation/HANDOFF_L401_distance_build1_brief_20261011.md,\n# Source+: section 2, Tony\'s ruling of 2026-10-11 ("approved as\n# Source+: recommended") -- one meter per second, printed as 0.001 km/s,\n# Source+: for a speed with no stated error. The exponent of ten in km/s.\n\n# Centres with no solid surface: the surface line is left out for them,\n# all three reviewers agreeing (brief section 1). Words, not values.\nNO_SOLID_SURFACE = {\'Sun\', \'Jupiter\', \'Saturn\', \'Uranus\', \'Neptune\', \'Planet 9\'}\n\n# The one local pair JPL states an accuracy for: the Moon\'s orbit about\n# Earth (and so about the Earth-Moon barycentre).\nEARTH_MOON_SYSTEM = {\'Moon\', \'Earth\', \'Earth-Moon Barycenter\'}\n\n\ndef _floor_err_km():\n    return HALF_UNIT * 10.0 ** DISTANCE_FLOOR_EXPONENT_KM\n\n\ndef _speed_floor_err_km_s():\n    return HALF_UNIT * 10.0 ** SPEED_FLOOR_EXPONENT_KM_S\n\n\ndef _row_err_km(row_name):\n    return HALF_UNIT * ROW_VALUES[row_name]\n\n\n# ============================================================================\n# WHO IS WHAT\n# ============================================================================\n\ndef _entry(name, objects):\n    for o in objects or ():\n        if o.get(\'name\') == name:\n            return o\n    return None\n\n\ndef parent_of(name, parent_planets):\n    """The body a satellite orbits, from parent_planets; a barycentre key is\n    used only when no body key lists it."""\n    found = None\n    for key, members in (parent_planets or {}).items():\n        if name in members:\n            if \'Barycenter\' not in key:\n                return key\n            found = found or key\n    return found\n\n\ndef is_local_pair(a, b, parent_planets):\n    pp = parent_planets or {}\n    return a in pp.get(b, ()) or b in pp.get(a, ())\n\n\ndef is_small_body_fetch(object_id, id_type):\n    """Is this a Horizons small-body target, which states its own\n    uncertainty? orbital_period\'s test by id_type, plus a small-body\n    record number (9 followed by seven digits), whatever its id_type: a\n    comet pinned by record can be listed with id_type \'id\'."""\n    if object_id is None:\n        return False\n    if _is_small_body(object_id, id_type):\n        return True\n    return bool(re.match(r\'^9\\d{7}$\', str(object_id).strip()))\n\n\ndef _finite_positive(x):\n    try:\n        x = float(x)\n    except (TypeError, ValueError):\n        return None\n    return x if (math.isfinite(x) and x > 0) else None\n\n\ndef body_kind(name, center_name, objects, parent_planets, obj_data=None):\n    """\n    One of: \'sun\', \'planet\', \'moon\' (Earth\'s), \'satellite\', \'small_body\',\n    \'small_body_other_record\', \'not_from_jpl\', \'unstated\'.\n    """\n    if obj_data is not None and (obj_data.get(\'analytical_position\')\n                                 or obj_data.get(\'not_fetched_for_date\')):\n        return \'not_from_jpl\'\n    if name == \'Sun\':\n        return \'sun\'\n    if name in PUBLISHED_ROW_NAMES:\n        return \'planet\'\n    if name == \'Moon\':\n        return \'moon\'\n    if name in SPACECRAFT_SHEET_ROWS:\n        return \'spacecraft_sheet\'\n    entry = _entry(name, objects) or {}\n    otype = entry.get(\'object_type\')\n    if otype in (\'hypothetical\', \'exoplanet\', \'exo_host_star\', \'exo_binary_star\',\n                 \'exo_barycenter\'):\n        return \'not_from_jpl\'\n    if otype == \'satellite\':\n        return \'satellite\'\n    fetch_id, fetch_type = entry.get(\'id\'), entry.get(\'id_type\')\n    if \'helio_id\' in entry:\n        if center_name == \'Sun\':\n            # palomas_orrery.py fetches these by their small-body solution\n            # in a Sun-centred plot.\n            fetch_id, fetch_type = entry[\'helio_id\'], \'smallbody\'\n        elif is_small_body_fetch(entry[\'helio_id\'], \'smallbody\'):\n            # From any other centre the system\'s record is fetched, which\n            # carries no uncertainty; JPL states one for the small body.\n            return \'small_body_other_record\'\n    if is_small_body_fetch(fetch_id, fetch_type):\n        return \'small_body\'\n    return \'unstated\'\n\n\ndef _gap(name, reason, what=None):\n    """The words for a part with no figure, true to why it has none."""\n    what = what or "%s\'s position" % name\n    if reason == \'not_fetched\':\n        return "JPL\'s figure for %s is not included here" % what\n    if reason == \'not_from_jpl\':\n        return \'no accuracy is stated for %s\' % what\n    # An unstated error is not a large one: a spacecraft is tracked by its\n    # radio signal\'s travel time and a moon by its orbit fit, so nothing\n    # here says the true uncertainty may be larger (Tony, 2026-10-12).\n    return \'JPL states no accuracy for %s\' % what\n\n\ndef _none_side(name, reason, what=None):\n    return {\'kind\': \'none\', \'name\': name, \'reason\': reason,\n            \'gap\': _gap(name, reason, what)}\n\n\ndef _may_be_larger(sides):\n    """Only a part JPL does give a figure for that is not included here,\n    or a position not from JPL at all, can make the true uncertainty\n    larger than the one printed; a part JPL simply states no figure for is\n    not, by that alone, a large one."""\n    return any(s.get(\'reason\') in (\'not_fetched\', \'not_from_jpl\') for s in sides)\n\n\ndef _side(name, role, center_name, obj_data, objects, parent_planets):\n    """\n    One side of the pair: the error that body\'s own position carries.\n    kind: \'reference\', \'published\', \'computed\', \'floor\' or \'none\'.\n    """\n    kind = body_kind(name, center_name, objects, parent_planets,\n                     obj_data if role == \'body\' else None)\n    if kind == \'sun\':\n        # The Sun adds nothing on either side: a planet\'s published\n        # accuracy is the accuracy of its orbit about the Sun, so the Sun\n        # seen from Earth is as well known as Earth seen from the Sun. Seen\n        # from a spacecraft or a barycentre the other side states nothing,\n        # and the pair has no stated error.\n        return {\'kind\': \'reference\', \'name\': name}\n    if kind == \'planet\':\n        row = PUBLISHED_ROW_NAMES[name]\n        return {\'kind\': \'published\', \'name\': name, \'err_km\': _row_err_km(row),\n                \'row\': row, \'who\': name}\n    if kind == \'moon\':\n        # About the Sun the Moon is Earth\'s orbit plus the Moon\'s about\n        # Earth; both are published, and the larger governs.\n        earth = _row_err_km(PUBLISHED_ROW_NAMES[\'Earth\'])\n        moon = _row_err_km(MOON_ROW_NAME)\n        if earth >= moon:\n            return {\'kind\': \'published\', \'name\': name, \'err_km\': earth,\n                    \'row\': PUBLISHED_ROW_NAMES[\'Earth\'], \'who\': \'Earth\'}\n        return {\'kind\': \'published\', \'name\': name, \'err_km\': moon,\n                \'row\': MOON_ROW_NAME, \'who\': \'the Moon\'}\n    if kind == \'satellite\':\n        parent = parent_of(name, parent_planets)\n        if parent in PUBLISHED_ROW_NAMES:\n            row = PUBLISHED_ROW_NAMES[parent]\n            return {\'kind\': \'floor\', \'name\': name, \'err_km\': _row_err_km(row),\n                    \'row\': row, \'who\': parent,\n                    \'gap\': _gap(name, \'unstated\',\n                                "%s\'s orbit around %s" % (name, parent))}\n        return _none_side(name, \'unstated\')\n    if kind == \'small_body\':\n        sig = (obj_data or {}).get(\'position_uncertainty\') if role == \'body\' else None\n        err = _finite_positive(sig.get(\'range_3sigma_km\')) if sig else None\n        if err is not None:\n            return {\'kind\': \'computed\', \'name\': name, \'err_km\': err,\n                    \'speed_err_km_s\': _finite_positive(sig.get(\'speed_3sigma_km_s\')),\n                    \'who\': name}\n        return _none_side(name, \'not_fetched\')\n    if kind == \'small_body_other_record\':\n        return _none_side(name, \'not_fetched\')\n    if kind == \'spacecraft_sheet\':\n        earth = _finite_positive((obj_data or {}).get(\'earth_distance_au\')) if role == \'body\' else None\n        if earth is None:\n            # Its distance from Earth was not fetched (the animation, or a\n            # centre): the sheet\'s figure is not included here.\n            return _none_side(name, \'not_fetched\')\n        ra, dec = (ROW_VALUES[r] for r in SPACECRAFT_SHEET_ROWS[name])\n        arcsec = max(ra, dec)\n        err = arcsec / ARCSEC_PER_DEG / DEG_PER_RAD * earth * KM_PER_AU\n        return {\'kind\': \'sheet\', \'name\': name, \'err_km\': err, \'who\': name,\n                \'arcsec\': arcsec}\n    if kind == \'not_from_jpl\':\n        return _none_side(name, \'not_from_jpl\')\n    return _none_side(name, \'unstated\')\n\n\ndef resolve_accuracy(obj_name, center_name, obj_data, objects, parent_planets):\n    """\n    The error state for one body seen from one centre, with the position\n    record it was fetched in (so keyed by body, centre and date).\n\n    Returns a dict:\n        state         \'published\', \'computed\', \'floor\', \'none\' or \'center\'\n        err_km        the governing distance error, before the floor\n                      (None for \'none\' and \'center\')\n        governs_kind  \'published\' or \'computed\': what kind of figure governs\n        reason        for \'none\': \'unstated\', \'not_fetched\' or \'not_from_jpl\'\n        who           the body whose figure governs\n        gap           for \'floor\' and \'none\': the words for the part with\n                      no figure, true to why it has none\n        speed_err_km_s  a small body\'s combined velocity 3-sigma, or None\n        row           the constants_new.py row that governs, or None\n    """\n    if obj_name == center_name:\n        return {\'state\': \'center\', \'err_km\': None}\n    if is_local_pair(obj_name, center_name, parent_planets):\n        pair = {obj_name, center_name}\n        if len(pair) == 2 and pair <= EARTH_MOON_SYSTEM:\n            # Inside the Earth-Moon system every distance is the Moon\'s\n            # orbit about Earth, or a fixed share of it.\n            return {\'state\': \'published\', \'err_km\': _row_err_km(MOON_ROW_NAME),\n                    \'governs_kind\': \'published\', \'row\': MOON_ROW_NAME,\n                    \'who\': \'the Moon\',\n                    \'orbit_words\': "the Moon\'s orbit around Earth"}\n        moon = obj_name if obj_name in (parent_planets or {}).get(center_name, ()) else center_name\n        host = center_name if moon == obj_name else obj_name\n        return {\'state\': \'none\', \'err_km\': None, \'reason\': \'unstated\',\n                \'gap\': _gap(moon, \'unstated\', "%s\'s orbit around %s" % (moon, host))}\n\n    b = _side(obj_name, \'body\', center_name, obj_data, objects, parent_planets)\n    c = _side(center_name, \'centre\', center_name, None, objects, parent_planets)\n    if b[\'kind\'] == \'none\':\n        # The body\'s own position has no figure. A centre whose own error is\n        # no larger than the kilometer floor changes nothing that prints, so\n        # the pair has none (a spacecraft seen from Earth). A centre with a\n        # larger error is a lower bound on the pair, by the larger-of-two\n        # ruling, and governs as a floor (a spacecraft seen from Neptune).\n        if c[\'kind\'] in (\'published\', \'computed\', \'floor\') and c[\'err_km\'] > _floor_err_km():\n            gap_sides = [s for s in (b, c) if s.get(\'gap\')]\n            return {\'state\': \'floor\', \'err_km\': c[\'err_km\'], \'who\': c[\'who\'],\n                    \'row\': c.get(\'row\'),\n                    \'governs_kind\': \'computed\' if c[\'kind\'] == \'computed\' else \'published\',\n                    \'speed_err_km_s\': None, \'published_sides\': [c],\n                    \'gap\': \'; \'.join(s[\'gap\'] for s in gap_sides),\n                    \'may_be_larger\': _may_be_larger(gap_sides)}\n        return {\'state\': \'none\', \'err_km\': None, \'reason\': b.get(\'reason\'),\n                \'gap\': b[\'gap\']}\n    sides = [s for s in (b, c) if s[\'kind\'] != \'reference\']\n    numeric = [s for s in sides if s[\'kind\'] in (\'published\', \'computed\', \'floor\', \'sheet\')]\n    nones = [s for s in sides if s[\'kind\'] == \'none\']\n    gov = max(numeric, key=lambda s: s[\'err_km\'])\n    small = [s for s in numeric if s[\'kind\'] == \'computed\']\n    out = {\'err_km\': gov[\'err_km\'], \'who\': gov[\'who\'], \'row\': gov.get(\'row\'),\n           \'arcsec\': gov.get(\'arcsec\'),\n           \'governs_kind\': gov[\'kind\'] if gov[\'kind\'] in (\'computed\', \'sheet\') else \'published\',\n           \'speed_err_km_s\': small[0].get(\'speed_err_km_s\') if small else None,\n           \'published_sides\': [s for s in numeric if s[\'kind\'] != \'computed\']}\n    gap_sides = nones + [s for s in numeric if s[\'kind\'] == \'floor\']\n    if gap_sides:\n        out[\'state\'] = \'floor\'\n        out[\'gap\'] = \'; \'.join(s[\'gap\'] for s in gap_sides)\n        out[\'may_be_larger\'] = _may_be_larger(gap_sides)\n    else:\n        out[\'state\'] = gov[\'kind\']\n    return out\n\n\n# ============================================================================\n# THE LINES\n# ============================================================================\n\ndef _fmt(value, err):\n    """value to the Report test\'s place for err, never fewer than one\n    figure, plain digits. err is always positive here: the floors see to\n    it, so format_by_error never falls back to ten figures."""\n    return format_by_error(value, err)\n\n\ndef _finite(x):\n    if isinstance(x, bool):\n        return False\n    try:\n        return math.isfinite(float(x))\n    except (TypeError, ValueError):\n        return False\n\n\ndef speed_error_km_s(acc, distance_km, speed_km_s):\n    """\n    The speed\'s error and what set it: (\'sigma\', \'relative\' or \'floor\').\n    """\n    state = acc[\'state\']\n    if state in (\'none\', \'center\') or speed_km_s is None:\n        return _speed_floor_err_km_s(), \'floor\'\n    dist_err = max(acc[\'err_km\'], _floor_err_km())\n    candidates = []\n    if distance_km and distance_km > 0:\n        if acc.get(\'governs_kind\') == \'computed\' and state == \'computed\':\n            for s in acc.get(\'published_sides\', ()):\n                e = max(s[\'err_km\'], _floor_err_km())\n                candidates.append((speed_km_s * e / distance_km, \'relative\'))\n        else:\n            candidates.append((speed_km_s * dist_err / distance_km, \'relative\'))\n        if acc.get(\'speed_err_km_s\') is None and state == \'computed\':\n            # A small body whose velocity columns came back empty: its speed\n            # keeps the distance\'s relative precision instead.\n            candidates.append((speed_km_s * dist_err / distance_km, \'relative\'))\n    if acc.get(\'speed_err_km_s\') is not None:\n        candidates.append((acc[\'speed_err_km_s\'], \'sigma\'))\n    if state == \'floor\':\n        candidates.append((_speed_floor_err_km_s(), \'floor\'))\n    if not candidates:\n        return _speed_floor_err_km_s(), \'floor\'\n    return max(candidates, key=lambda t: t[0])\n\n\ndef _distance_sentence(acc):\n    state = acc[\'state\']\n    if state == \'center\':\n        return [\'This body is the center of the plot.\']\n    if state == \'none\':\n        reason = acc.get(\'reason\')\n        if reason == \'not_fetched\':\n            return ["JPL\'s uncertainty for this position is not included here,",\n                    \'so distances are shown to the whole kilometer.\']\n        if reason == \'not_from_jpl\':\n            return [\'No accuracy is stated for this position,\',\n                    \'so distances are shown to the whole kilometer.\']\n        return [\'JPL states no accuracy for this position,\',\n                \'so distances are shown to the whole kilometer.\']\n    computed = acc.get(\'governs_kind\') == \'computed\'\n    finer = acc[\'err_km\'] < _floor_err_km()\n    orbit = acc.get(\'orbit_words\') or "%s\'s orbit" % acc[\'who\']\n    if acc.get(\'governs_kind\') == \'sheet\':\n        # JPL states the Voyagers\' uncertainty as an angle seen from Earth,\n        # predicted for 2030, and none for the distance; the conversion at\n        # the spacecraft\'s distance from Earth is ours, and the words say so.\n        km = float(\'%.2g\' % acc[\'err_km\'])\n        lines = ["These distances are rounded to JPL\'s predicted sky-position uncertainty",\n                 \'for %s in 2030, %s arcseconds seen from Earth: about %s km\'\n                 % (acc[\'who\'], \'%.*g\' % (SHEET_FIGURES, acc[\'arcsec\']),\n                    \'{:,}\'.format(int(km))),\n                 \'at its distance. JPL states none for the distance itself,\',\n                 \'so this conversion is ours.\']\n    elif finer:\n        lines = [\'These distances are shown to the whole kilometer;\',\n                 ("JPL\'s uncertainty for %s\'s position on this date is finer."\n                  % acc[\'who\'] if computed\n                  else "JPL\'s published accuracy for %s is finer." % orbit)]\n    elif computed:\n        lines = ["These distances are rounded to JPL\'s uncertainty for %s\'s position"\n                 % acc[\'who\'], \'on this date, at three standard deviations.\']\n    else:\n        lines = ["These distances are rounded to JPL\'s published accuracy for",\n                 \'%s.\' % orbit]\n    if state == \'floor\':\n        lines[-1] = lines[-1].rstrip(\'.\') + \';\'\n        gaps = acc[\'gap\'].split(\'; \')\n        if acc.get(\'may_be_larger\'):\n            lines += [g + \',\' for g in gaps]\n            lines.append(\'so the true uncertainty may be larger.\')\n        else:\n            lines += [g + \';\' for g in gaps[:-1]] + [gaps[-1] + \'.\']\n    return lines\n\n\ndef _speed_sentence(acc, speed_from):\n    state = acc[\'state\']\n    if state == \'center\':\n        return []\n    if state == \'none\':\n        reason = acc.get(\'reason\')\n        if reason == \'not_fetched\':\n            return ["JPL\'s uncertainty for this body\'s speed is not included here."]\n        if reason == \'not_from_jpl\':\n            return [\'No uncertainty is stated for this speed.\']\n        return ["JPL states no uncertainty for this body\'s speed."]\n    if speed_from == \'sigma\':\n        return ["The speed is rounded to JPL\'s uncertainty in its velocity."]\n    if speed_from == \'floor\':\n        return [\'Part of this speed has no stated uncertainty,\',\n                \'so it is shown to the meter per second.\']\n    return [\'The speed is rounded to the same relative precision as the distance.\']\n\n\ndef distance_speed_lines(acc, distance_au, speed_au_per_day, center_name,\n                         center_radius_km):\n    """\n    The hover\'s distance and speed lines, in order, each without <br>.\n    Every unit is placed by its own Report test of the same error.\n    """\n    lines = []\n    is_center = acc[\'state\'] == \'center\'\n    err_km = _floor_err_km() if acc[\'state\'] in (\'none\', \'center\') else max(\n        acc[\'err_km\'], _floor_err_km())\n    if _finite(distance_au):\n        distance_au = float(distance_au)\n        dist_km = distance_au * KM_PER_AU\n        err_au = err_km / KM_PER_AU\n        lines.append(\'Distance from Center: %s AU\' % _fmt(distance_au, err_au))\n        lines.append(\'Distance: %s kilometers\' % _fmt(dist_km, err_km))\n        # One light-time line: light-minutes under an hour, light-hours\n        # above (brief section 1).\n        lh_per_km = 1.0 / SPEED_OF_LIGHT_KM_S / S_PER_HOUR\n        if dist_km * lh_per_km < 1:\n            lines.append(\'Distance: %s light-minutes\' % _fmt(\n                distance_au * LIGHT_MINUTES_PER_AU, err_au * LIGHT_MINUTES_PER_AU))\n        else:\n            lines.append(\'Distance: %s light-hours\' % _fmt(\n                dist_km * lh_per_km, err_km * lh_per_km))\n        if (not is_center and center_radius_km\n                and center_name not in NO_SOLID_SURFACE):\n            surf = dist_km - center_radius_km\n            s = _fmt(surf, err_km)\n            if surf < 0:\n                s += \' (below mean datum)\'\n            lines.append(\'Distance to Center Surface: %s kilometers\' % s)\n    else:\n        dist_km = None\n        lines.append(\'Distance from Center: N/A AU\')\n        lines.append(\'Distance: N/A kilometers\')\n        lines.append(\'Distance: N/A light-minutes\')\n\n    speed_from = None\n    if _finite(speed_au_per_day):\n        km_s = float(speed_au_per_day) * KM_PER_AU / S_PER_DAY\n        v_err, speed_from = speed_error_km_s(acc, dist_km, km_s)\n        lines.append(\'Velocity: %s AU/day\' % _fmt(\n            float(speed_au_per_day), v_err * S_PER_DAY / KM_PER_AU))\n        lines.append(\'Velocity: %s km/hr (%s km/sec)\' % (\n            _fmt(km_s * S_PER_HOUR, v_err * S_PER_HOUR), _fmt(km_s, v_err)))\n    else:\n        lines.append(\'Velocity: N/A AU/day\')\n        lines.append(\'Velocity: N/A km/hr (N/A km/sec)\')\n    lines += _distance_sentence(acc)\n    if speed_from is not None:\n        lines += _speed_sentence(acc, speed_from)\n    return lines\n\n\n# ============================================================================\n# FETCHING A SMALL BODY\'S UNCERTAINTY WITH ITS POSITION (Horizons, 2xr)\n# ============================================================================\n\n# Horizons\' column names for the 2xr table, read by name and never by\n# position (read live 2026-10-12 for 2P/Encke and 90377 Sedna through the\n# chat\'s web-fetch tool). With OUT_UNITS=\'AU-D\' the position columns are\n# in AU and the velocity columns in AU/day, uncertainties included.\nSTATE_COLUMNS = (\'X\', \'Y\', \'Z\', \'VX\', \'VY\', \'VZ\')\nSIGMA_COLUMNS = (\'R_s\', \'VR_s\', \'VT_s\', \'VN_s\')\n\n\ndef _num(tok):\n    tok = tok.strip()\n    if not tok or tok.lower().strip(\'.\') in (\'n.a\', \'na\'):\n        return None\n    try:\n        return float(tok)\n    except ValueError:\n        return None\n\n\ndef parse_vectors_2xr(text):\n    """\n    The rows of a Horizons vector table, as dicts keyed by column name.\n    Raises ValueError, quoting Horizons, when there is no data block.\n    """\n    lines = text.split(\'\\n\')\n    try:\n        soe = next(i for i, ln in enumerate(lines) if \'$$SOE\' in ln)\n        eoe = next(i for i, ln in enumerate(lines) if \'$$EOE\' in ln)\n    except StopIteration:\n        snippet = \' | \'.join(ln.strip() for ln in lines if ln.strip())[:400]\n        raise ValueError(\'Horizons returned no vector table: %s\' % snippet)\n    header = None\n    for ln in reversed(lines[:soe]):\n        if \'JDTDB\' in ln and \',\' in ln:\n            header = ln\n            break\n    if header is None:\n        raise ValueError(\'Horizons vector table has no column header\')\n    names = [h.strip() for h in header.split(\',\')]\n    if names and \'JDTDB\' in names[0] and \'Calendar\' in names[0]:\n        names = [\'JDTDB\', \'Calendar Date (TDB)\'] + names[1:]\n    rows = []\n    for ln in lines[soe + 1:eoe]:\n        if not ln.strip() or \'Cut-off\' in ln:\n            continue\n        toks = ln.split(\',\')\n        row = {}\n        for name, tok in zip(names, toks):\n            if name:\n                row[name] = tok.strip() if name.startswith(\'Calendar\') else _num(tok)\n        rows.append(row)\n    missing = [c for c in STATE_COLUMNS if c not in names]\n    if missing:\n        raise ValueError(\'Horizons vector table lacks columns %s\' % \', \'.join(missing))\n    return rows\n\n\ndef uncertainty_record(row, body_id, location, jd):\n    """The hover\'s error record from one 2xr row, keyed by body, centre and\n    date. Fields carry the sigma level in their names."""\n    # A sigma of zero, or one that is not a number, is no figure.\n    r_s = _finite_positive(row.get(\'R_s\'))\n    v = [row.get(c) for c in (\'VR_s\', \'VT_s\', \'VN_s\')]\n    v = [x if (x is not None and math.isfinite(x) and x >= 0) else None for x in v]\n    rec = {\n        \'source\': "JPL Horizons vector table 2xr, 1-sigma columns times %d" % SIGMA_MULTIPLE,\n        \'key\': {\'body\': str(body_id), \'center\': str(location), \'jd\': jd},\n        \'range_1sigma_au\': r_s,\n        \'velocity_1sigma_rtn_au_per_day\': v,\n        \'range_3sigma_km\': (SIGMA_MULTIPLE * r_s * KM_PER_AU) if r_s is not None else None,\n        \'speed_3sigma_km_s\': None,\n    }\n    if all(x is not None for x in v) and any(x > 0 for x in v):\n        combined = math.sqrt(sum(x * x for x in v))\n        rec[\'speed_3sigma_km_s\'] = (SIGMA_MULTIPLE * combined * KM_PER_AU\n                                    / (S_PER_DAY))\n    return rec\n\n\ndef fetch_small_body_state(object_id, id_type, location, jd, timeout=60):\n    """\n    One Horizons vector query for a small body at one date, asking for the\n    2xr table: the position and velocity, and their 1-sigma uncertainties,\n    in the same answer. astroquery 0.4.11 sets no VEC_TABLE and cannot\n    parse the extra columns, so the request is the payload astroquery\n    builds, with VEC_TABLE added, sent directly. No extra query.\n\n    Returns (state, uncertainty_record): state has x, y, z (AU), vx, vy,\n    vz (AU/day), range (AU) and range_rate (AU/day). Raises on failure.\n    """\n    import requests\n    from astroquery.jplhorizons import Horizons, conf\n    h = Horizons(id=object_id, id_type=id_type, location=location, epochs=[jd])\n    payload = h.vectors(get_query_payload=True)\n    payload[\'VEC_TABLE\'] = "\'2xr\'"\n    payload[\'OBJ_DATA\'] = \'NO\'\n    resp = requests.get(conf.horizons_server, params=payload, timeout=timeout)\n    resp.raise_for_status()\n    rows = parse_vectors_2xr(resp.text)\n    if not rows:\n        raise ValueError(\'Horizons returned an empty vector table\')\n    row = rows[0]\n    x, y, z = row[\'X\'], row[\'Y\'], row[\'Z\']\n    vx, vy, vz = row[\'VX\'], row[\'VY\'], row[\'VZ\']\n    if None in (x, y, z, vx, vy, vz):\n        raise ValueError(\'Horizons vector table has an empty state column\')\n    rng = math.sqrt(x * x + y * y + z * z)\n    state = {\'x\': x, \'y\': y, \'z\': z, \'vx\': vx, \'vy\': vy, \'vz\': vz,\n             \'range\': rng,\n             \'range_rate\': (x * vx + y * vy + z * vz) / rng if rng else 0.0}\n    return state, uncertainty_record(row, object_id, location, jd)\n',
    'test_position_digits.py': '"""\ntest_position_digits.py - the orrery\'s body hover prints each distance and\nspeed to the digits JPL\'s errors earn, and proof that this check can fail.\n\nThe body hover (visualization_utils.format_detailed_hover_text, which the\nstatic plot, the animation and the social export all use) once printed\nten decimal places of an AU and ten figures of a kilometre for every body\n(L-401). Since build 1 it prints by the error position_accuracy.py works\nout. This file builds the hover for a fixed set of bodies and centres,\noffline, and judges every distance and speed line against errors it works\nout ITSELF: from the rows in constants_new.py read by name, from the\nfixture\'s own 3-sigma figures, and from the stated floors. It shares no\narithmetic with position_accuracy.py, so a fault there shows here.\n\nIt first plants a fault for each thing it must catch, and requires the\nright finding, by name:\n\n    planted                                      must be caught as\n    Jupiter\'s row read ten times finer           PLANET FINER THAN ITS ROW\n    a missing sigma turned into a tiny one       SMALL BODY WITHOUT SIGMA NOT IN THE NO-ERROR STATE\n    the kilometer floor moved to meters          NO-ERROR BODY FINER THAN THE FLOOR\n    the light-time line left out                 LINE DROPPED\n    a typed sky value put back                   TYPED SKY VALUE\n    the speed\'s error divided by a thousand      SPEED FINER THAN ITS DISTANCE\n    fetch_position\'s 2xr call removed            DISPATCH\n    the 2xr columns read by position             2XR READ BY POSITION\n    a no-error body ignoring its centre\'s error  NO-ERROR BODY IGNORES ITS CENTRE\n    a zero sigma taken as a figure               ZERO SIGMA TAKEN AS A FIGURE\n    the Voyagers\' data-sheet figures dropped     SPACECRAFT DATA-SHEET FIGURE IGNORED\n\nThe last five go beyond the brief\'s six. The first two prove the static\nplot still asks for a small body\'s uncertainty and reads Horizons\'\ncolumns by name, against an answer recorded from JPL; the last two come\nfrom a cold review of the build (2026-10-12), with its other cases: a\npair must print the same digits from either end, and every listed\nobject is hovered from the Sun, Earth and Neptune. The fifth comes\nfrom Tony\'s ruling of the same day (option A): a spacecraft whose\nHorizons data sheet states a predicted pointing angle (the Voyagers)\nprints by that angle at its distance from Earth.\n\nThen it judges the real code. The last line starts "POSITION DIGITS:",\nwhich the maintenance run quotes, and says what was compared and how many\nhovers were examined.\n\nRun (VS Code Run button, or):\n    python test_position_digits.py\n\nNever contacts Horizons. Live behaviour is the patch\'s live check and\nTony\'s look.\n\nRole: devtool\nDomain: dev_tools\n\nModule created: October 12, 2026 with Anthropic\'s Claude Opus 5.5 (L-401,\nbuild 1).\n"""\nimport math\nimport os\nimport re\nimport sys\nfrom contextlib import contextmanager\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nif HERE not in sys.path:\n    sys.path.insert(0, HERE)\n\nimport constants_new as cn\nimport celestial_coordinates\nimport position_accuracy as pa\nfrom celestial_objects import OBJECT_DEFINITIONS\nfrom orbital_elements import parent_planets\nfrom visualization_utils import format_detailed_hover_text\n\n# ============================================================================\n# THE CHECKER\'S OWN ARITHMETIC (shares nothing with position_accuracy.py)\n# ============================================================================\n\n# The checker\'s own copies of the two stated floors, as half-units, kept\n# apart from position_accuracy.py on purpose so a fault there shows here.\nFLOOR_KM = 0.5\n# Source: documentation/DESIGN_L401_distance_digits_rulings_20261011.md,\n# Source+: section 4, item 4 -- whole kilometers; half of one is the error.\nSPEED_FLOOR_KM_S = 0.0005\n# Source: documentation/HANDOFF_L401_distance_build1_brief_20261011.md,\n# Source+: section 2 -- one meter per second; half of it is the error.\nDAY_S = cn.S_PER_DAY\n\n\ndef place_for(err):\n    """The Report test, written out: the power of ten whose half-unit is\n    nearest err on a log scale, a tie going to the coarser."""\n    best = None\n    for p in range(-20, 21):\n        d = abs(math.log10(0.5 * 10.0 ** p) - math.log10(err))\n        if best is None or d < best[0] - 1e-12 or (abs(d - best[0]) <= 1e-12 and p > best[1]):\n            best = (d, p)\n    return best[1]\n\n\ndef expected_place(value, err):\n    p = place_for(err)\n    if value:\n        top = int(math.floor(math.log10(abs(value))))\n        p = min(p, top)\n    return p\n\n\ndef printed_place(s):\n    s = s.replace(\',\', \'\')\n    if \'.\' in s:\n        return -len(s.split(\'.\')[1])\n    stripped = s.lstrip(\'-\')\n    return len(stripped) - len(stripped.rstrip(\'0\')) if stripped.strip(\'0\') else 0\n\n\ndef matches(s, value, p):\n    """Does the printed string s carry value at place p, no finer, no coarser?"""\n    t = s.replace(\',\', \'\')\n    try:\n        got = float(t)\n    except ValueError:\n        return False\n    if p < 0:\n        if \'.\' not in t or len(t.split(\'.\')[1]) != -p:\n            return False\n        return abs(got - round(value, -p)) <= 0.5 * 10.0 ** p + 1e-9 * abs(value)\n    if \'.\' in t:\n        return False\n    want = round(value / 10.0 ** p) * 10.0 ** p\n    return abs(got - want) <= 1e-6 * max(1.0, abs(want))\n\n\ndef row(name):\n    return 0.5 * getattr(cn, name)\n\n\n# ============================================================================\n# THE FIXTURES: bodies, centres, positions, and what each must print by\n# ============================================================================\n\ndef _od(r_au, v_km_s, sigma=None, missing=False, ra_sigma=None, earth_au=None):\n    v = v_km_s * DAY_S / cn.KM_PER_AU\n    d = {\'x\': r_au, \'y\': 0.0, \'z\': 0.0, \'vx\': 0.0, \'vy\': v, \'vz\': 0.0,\n         \'velocity\': v, \'ra\': 123.4567, \'dec\': -12.3456,\n         \'ra_3sigma\': ra_sigma, \'dec_3sigma\': ra_sigma}\n    if sigma:\n        d[\'position_uncertainty\'] = {\'range_3sigma_km\': sigma[0],\n                                     \'speed_3sigma_km_s\': sigma[1],\n                                     \'key\': {\'body\': \'fixture\'}}\n    if missing:\n        d[\'position_uncertainty\'] = {\'missing\': \'fixture: no 2xr columns\',\n                                     \'key\': {\'body\': \'fixture\'}}\n    if earth_au is not None:\n        d[\'earth_distance_au\'] = earth_au\n    return d\n\n\ndef sheet_err_km(name, earth_au):\n    """The checker\'s own conversion of a Voyager\'s data-sheet angle: the\n    larger of RA and DEC, from the rows by name, at its distance from Earth."""\n    n = name.split()[-1]\n    arcsec = max(getattr(cn, \'VOYAGER_%s_POINTING_RA_2030_ARCSEC\' % n),\n                 getattr(cn, \'VOYAGER_%s_POINTING_DEC_2030_ARCSEC\' % n))\n    return math.radians(arcsec / 3600.0) * earth_au * cn.KM_PER_AU\n\n\n# (name, centre, obj_data, state, distance error, speed rule)\n#   distance error: (\'row\', NAME) | (\'sigma\', km) | (\'floor\',)\n#   speed rule:     \'relative\' | (\'sigma\', km/s) | \'floor\' | \'floor_or_relative\'\nFIXTURES = [\n    (\'Mercury\', \'Sun\', _od(0.3871, 47.36), \'published\',\n     (\'row\', \'DE430_TERRESTRIAL_POSITION_PLACE_KM\'), \'relative\'),\n    (\'Jupiter\', \'Sun\', _od(5.2034, 13.07), \'published\',\n     (\'row\', \'DE430_JUPITER_SATURN_POSITION_PLACE_KM\'), \'relative\'),\n    (\'Neptune\', \'Sun\', _od(29.91, 5.43), \'published\',\n     (\'row\', \'DE430_URANUS_NEPTUNE_PLUTO_POSITION_PLACE_KM\'), \'relative\'),\n    (\'Mars\', \'Earth\', _od(0.5214, 15.2), \'published\',\n     (\'row\', \'DE430_TERRESTRIAL_POSITION_PLACE_KM\'), \'relative\'),\n    (\'Moon\', \'Earth\', _od(0.002570, 1.022), \'published\',\n     (\'row\', \'DE430_MOON_POSITION_PLACE_KM\'), \'relative\'),\n    (\'Sun\', \'Jupiter\', _od(5.2034, 13.07), \'published\',\n     (\'row\', \'DE430_JUPITER_SATURN_POSITION_PLACE_KM\'), \'relative\'),\n    (\'Sedna\', \'Sun\', _od(85.13, 4.30, sigma=(257820.0, 2.5476e-4), ra_sigma=0.41),\n     \'computed\', (\'sigma\', 257820.0), (\'sigma\', 2.5476e-4)),\n    (\'Encke\', \'Sun\', _od(2.0108, 33.17, sigma=(1012.3, 1.3e-5), ra_sigma=0.9),\n     \'computed\', (\'sigma\', 1012.3), (\'sigma\', 1.3e-5)),\n    (\'Sedna\', \'Sun\', _od(85.13, 4.30, missing=True), \'none\', (\'floor\',), \'floor\'),\n    (\'Io\', \'Jupiter\', _od(0.0028189, 17.33), \'none\', (\'floor\',), \'floor\'),\n    (\'Io\', \'Sun\', _od(5.2001, 12.9), \'floor\',\n     (\'row\', \'DE430_JUPITER_SATURN_POSITION_PLACE_KM\'), \'floor_or_relative\'),\n    # Voyager 1 and 2: JPL\'s data sheets state a predicted pointing angle\n    # (Tony\'s option A, 2026-10-12); with no distance from Earth fetched (the\n    # animation) the figure is not included.\n    (\'Voyager 1\', \'Sun\', _od(170.22, 16.9, earth_au=170.9), \'sheet\',\n     (\'sheet\', \'Voyager 1\', 170.9), \'relative\'),\n    (\'Voyager 1\', \'Sun\', _od(170.22, 16.9), \'none\', (\'floor\',), \'floor\'),\n    (\'EM-L1\', \'Earth\', _od(0.002186, 0.85), \'none\', (\'floor\',), \'floor\'),\n    (\'Pluto\', \'Pluto-Charon Barycenter\', _od(1.4e-5, 0.02), \'none\', (\'floor\',), \'floor\'),\n    # From the cold review of 2026-10-12: a no-error body seen from a centre\n    # with a larger error takes that error as a floor; a small body\'s own\n    # figure governing a floor case keeps the computed words; the\n    # Earth-Moon system; a small-body record listed by id_type \'id\'; a\n    # system record fetched where JPL states the small body\'s figure; a\n    # zero sigma.\n    (\'Voyager 2\', \'Neptune\', _od(114.3, 15.3, earth_au=144.6), \'sheet\',\n     (\'sheet\', \'Voyager 2\', 144.6), \'relative\'),\n    (\'EM-L1\', \'Neptune\', _od(29.9, 5.4), \'floor\',\n     (\'row\', \'DE430_URANUS_NEPTUNE_PLUTO_POSITION_PLACE_KM\'), \'floor_or_relative\'),\n    (\'Sedna\', \'Neptune\', _od(55.2, 6.1, missing=True), \'floor\',\n     (\'row\', \'DE430_URANUS_NEPTUNE_PLUTO_POSITION_PLACE_KM\'), \'floor_or_relative\'),\n    (\'Sedna\', \'Io\', _od(80.4, 12.0, sigma=(257820.0, 2.5476e-4)), \'floor\',\n     (\'sigma\', 257820.0), \'sigma_or_floor\'),\n    (\'Earth\', \'Earth-Moon Barycenter\', _od(3.1e-5, 0.012), \'published\',\n     (\'row\', \'DE430_MOON_POSITION_PLACE_KM\'), \'relative\'),\n    (\'C/2025_K1\', \'Sun\', _od(3.2, 22.0, missing=True), \'none\', (\'floor\',), \'floor\'),\n    (\'Makemake\', \'Earth\', _od(52.6, 30.1), \'none\', (\'floor\',), \'floor\'),\n    (\'Encke\', \'Sun\', _od(2.0108, 33.17, sigma=(0.0, 0.0)), \'none\', (\'floor\',), \'floor\'),\n]\n\n# What each fixture\'s sentences must say, and must not, beyond its state:\n# a sentence check by substring alone cannot see a false sentence.\nWORDS = {\n    (\'Sedna\', \'Io\'): (["JPL\'s uncertainty for Sedna\'s position",\n                       "JPL states no accuracy for Io\'s orbit around Jupiter"],\n                      [\'published accuracy\', \'may be larger\']),\n    # Tony, 2026-10-12: an unstated error is not called a large one; then,\n    # on Fable\'s reading of the Voyager 2 data sheet, option A: the sheet\'s\n    # angle, converted at the distance from Earth, said to be ours.\n    (\'Voyager 2\', \'Neptune\'): (["predicted sky-position uncertainty",\n                                "for Voyager 2 in 2030, 4.718 arcseconds",\n                                "JPL states none for the distance itself",\n                                "so this conversion is ours"],\n                               [\'may be larger\', \'JPL states no accuracy\']),\n    (\'Voyager 1\', \'Sun\'): ([], [\'JPL states no accuracy\']),\n    (\'EM-L1\', \'Neptune\'): (["published accuracy for", "Neptune\'s orbit",\n                            "JPL states no accuracy for EM-L1\'s position"],\n                           [\'may be larger\']),\n    (\'Sedna\', \'Neptune\'): (["JPL\'s figure for Sedna\'s position is not included here",\n                            "may be larger"],\n                           ["JPL states no accuracy for Sedna"]),\n    (\'Earth\', \'Earth-Moon Barycenter\'): (["the Moon\'s orbit around Earth"],\n                                         [\'JPL states no accuracy\']),\n    (\'C/2025_K1\', \'Sun\'): (["is not included here"], [\'JPL states no accuracy\']),\n    (\'Makemake\', \'Earth\'): (["is not included here"], [\'JPL states no accuracy\']),\n    (\'Io\', \'Sun\'): (["JPL states no accuracy for Io\'s orbit around Jupiter"],\n                    [\'may be larger\']),\n}\n\nSENTENCES = {\n    \'published\': "published accuracy for",\n    \'computed\': "on this date, at three standard deviations",\n    \'floor\': "These distances are",\n    \'sheet\': "predicted sky-position uncertainty",\n}\nNONE_WORDS = {\n    \'not_fetched\': "JPL\'s uncertainty for this position is not included here",\n    \'unstated\': "JPL states no accuracy for this position",\n}\nSPEED_WORDS = {\n    \'relative\': "same relative precision as the distance",\n    \'sigma\': "JPL\'s uncertainty in its velocity",\n    \'floor\': "JPL states no uncertainty for this body\'s speed",\n    \'not_fetched\': "JPL\'s uncertainty for this body\'s speed is not included here",\n}\n\n\ndef _hover(name, centre, obj_data):\n    full, _mini, _note = format_detailed_hover_text(\n        dict(obj_data), name, centre, OBJECT_DEFINITIONS, {}, parent_planets,\n        cn.CENTER_BODY_RADII, cn.KM_PER_AU, cn.LIGHT_MINUTES_PER_AU,\n        cn.KNOWN_ORBITAL_PERIODS)\n    return full.split(\'<br>\')\n\n\ndef _find(lines, pattern):\n    for ln in lines:\n        m = re.match(pattern, ln)\n        if m:\n            return m\n    return None\n\n\ndef judge_fixture(fx, findings, counts):\n    name, centre, od, state, derr, srule = fx\n    tag = \'%s from %s\' % (name, centre)\n    acc = pa.resolve_accuracy(name, centre, od, OBJECT_DEFINITIONS, parent_planets)\n    if acc[\'state\'] != state:\n        pu = od.get(\'position_uncertainty\') or {}\n        if state == \'none\' and pu.get(\'missing\'):\n            findings.append((\'SMALL BODY WITHOUT SIGMA NOT IN THE NO-ERROR STATE\',\n                             \'%s: state %r, expected none\' % (tag, acc[\'state\'])))\n        elif state == \'sheet\':\n            findings.append((\'SPACECRAFT DATA-SHEET FIGURE IGNORED\',\n                             \'%s: state %r, expected the data sheet\\\'s figure\' % (tag, acc[\'state\'])))\n        elif state == \'none\' and pu.get(\'range_3sigma_km\') == 0.0:\n            findings.append((\'ZERO SIGMA TAKEN AS A FIGURE\',\n                             \'%s: state %r, expected none\' % (tag, acc[\'state\'])))\n        elif state == \'floor\' and acc[\'state\'] == \'none\':\n            findings.append((\'NO-ERROR BODY IGNORES ITS CENTRE\',\n                             \'%s: state none, expected the centre as a floor\' % tag))\n        else:\n            findings.append((\'WRONG STATE\', \'%s: state %r, expected %r\'\n                             % (tag, acc[\'state\'], state)))\n    lines = _hover(name, centre, od)\n    counts[\'hovers\'] += 1\n    text = \'\\n\'.join(lines)\n\n    # The error this fixture must print by, worked out here.\n    if derr[0] == \'row\':\n        err_km = max(row(derr[1]), FLOOR_KM)\n        governs = \'row\' if row(derr[1]) >= FLOOR_KM else \'floor\'\n    elif derr[0] == \'sigma\':\n        err_km = max(derr[1], FLOOR_KM)\n        governs = \'sigma\' if derr[1] >= FLOOR_KM else \'floor\'\n    elif derr[0] == \'sheet\':\n        err_km = max(sheet_err_km(derr[1], derr[2]), FLOOR_KM)\n        governs = \'sheet\'\n    else:\n        err_km, governs = FLOOR_KM, \'floor\'\n    dist_au = math.sqrt(od[\'x\'] ** 2 + od[\'y\'] ** 2 + od[\'z\'] ** 2)\n    dist_km = dist_au * cn.KM_PER_AU\n    lm = dist_au * cn.LIGHT_MINUTES_PER_AU\n    err_au = err_km / cn.KM_PER_AU\n    err_lm = err_au * cn.LIGHT_MINUTES_PER_AU\n\n    distance_lines = [\n        (\'AU\', r\'Distance from Center: ([-\\d,.]+) AU$\', dist_au, err_au),\n        (\'kilometers\', r\'Distance: ([-\\d,.]+) kilometers$\', dist_km, err_km),\n    ]\n    if lm < 60:\n        distance_lines.append((\'light-minutes\', r\'Distance: ([-\\d,.]+) light-minutes$\', lm, err_lm))\n    else:\n        distance_lines.append((\'light-hours\', r\'Distance: ([-\\d,.]+) light-hours$\',\n                               lm / 60, err_lm / 60))\n    radius = cn.CENTER_BODY_RADII.get(centre)\n    if radius and centre not in (\'Sun\', \'Jupiter\', \'Saturn\', \'Uranus\', \'Neptune\', \'Planet 9\'):\n        distance_lines.append((\'surface\', r\'Distance to Center Surface: ([-\\d,.]+)\',\n                               dist_km - radius, err_km))\n    elif _find(lines, r\'Distance to Center Surface\'):\n        findings.append((\'SURFACE LINE WITHOUT A SURFACE\', \'%s: %s has no solid surface\'\n                         % (tag, centre)))\n\n    for unit, pat, value, err in distance_lines:\n        m = _find(lines, pat)\n        if not m:\n            findings.append((\'LINE DROPPED\', \'%s: no %s line\' % (tag, unit)))\n            continue\n        counts[\'lines\'] += 1\n        p = expected_place(value, err)\n        if not matches(m.group(1), value, p):\n            got = printed_place(m.group(1))\n            if got < p and state == \'none\':\n                cls = \'NO-ERROR BODY FINER THAN THE FLOOR\'\n            elif got < p and governs == \'row\':\n                cls = \'PLANET FINER THAN ITS ROW\'\n            elif got < p and governs == \'sheet\':\n                cls = \'SPACECRAFT FINER THAN ITS DATA SHEET\'\n            elif got < p and governs == \'floor\':\n                cls = \'FINER THAN THE FLOOR\'\n            elif got < p:\n                cls = \'FINER THAN ITS SIGMA\'\n            else:\n                cls = \'WRONG DIGITS\'\n            findings.append((cls, \'%s, %s line: printed %s, expected the 10^%d place\'\n                             % (tag, unit, m.group(1), p)))\n\n    # The speed, by the rule this fixture names.\n    speed_km_s = od[\'velocity\'] * cn.KM_PER_AU / DAY_S\n    if srule == \'relative\':\n        v_err = speed_km_s * err_km / dist_km\n    elif srule == \'floor\':\n        v_err = SPEED_FLOOR_KM_S\n    elif srule == \'floor_or_relative\':\n        v_err = max(SPEED_FLOOR_KM_S, speed_km_s * err_km / dist_km)\n    elif srule == \'sigma_or_floor\':\n        v_err = max(SPEED_FLOOR_KM_S, 2.5476e-4)\n    else:\n        v_err = srule[1]\n    speed_lines = [\n        (\'AU/day\', r\'Velocity: ([-\\d,.]+) AU/day$\', od[\'velocity\'],\n         v_err * DAY_S / cn.KM_PER_AU),\n        (\'km/hr\', r\'Velocity: ([-\\d,.]+) km/hr\', speed_km_s * 3600, v_err * 3600),\n        (\'km/sec\', r\'Velocity: .* km/hr \\(([-\\d,.]+) km/sec\\)$\', speed_km_s, v_err),\n    ]\n    for unit, pat, value, err in speed_lines:\n        m = _find(lines, pat)\n        if not m:\n            findings.append((\'LINE DROPPED\', \'%s: no speed line in %s\' % (tag, unit)))\n            continue\n        counts[\'lines\'] += 1\n        p = expected_place(value, err)\n        if not matches(m.group(1), value, p):\n            got = printed_place(m.group(1))\n            cls = (\'SPEED FINER THAN ITS DISTANCE\' if got < p and srule == \'relative\'\n                   else \'SPEED FINER THAN ITS ERROR\' if got < p\n                   else \'WRONG SPEED DIGITS\')\n            findings.append((cls, \'%s, speed in %s: printed %s, expected the 10^%d place\'\n                             % (tag, unit, m.group(1), p)))\n\n    # The sentences: which kind of figure, in words.\n    if state == \'none\':\n        reason = (\'not_fetched\' if (od.get(\'position_uncertainty\')\n                                    or (name, centre) in ((\'Makemake\', \'Earth\'),)\n                                    or name in (\'Voyager 1\', \'Voyager 2\'))\n                  else \'unstated\')\n        if NONE_WORDS[reason] not in text:\n            cls = (\'SMALL BODY WITHOUT SIGMA NOT IN THE NO-ERROR STATE\'\n                   if reason == \'not_fetched\' else \'LINE DROPPED\')\n            findings.append((cls, \'%s: the no-error sentence is missing\' % tag))\n        want = SPEED_WORDS[\'not_fetched\' if reason == \'not_fetched\' else \'floor\']\n    else:\n        if SENTENCES[state] not in text:\n            findings.append((\'LINE DROPPED\', \'%s: the %s sentence is missing\' % (tag, state)))\n        want = None if srule in (\'floor_or_relative\', \'sigma_or_floor\') else SPEED_WORDS[\n            srule if isinstance(srule, str) else \'sigma\']\n    if want and want not in text:\n        findings.append((\'LINE DROPPED\', \'%s: the speed sentence is missing\' % tag))\n    must, mustnot = WORDS.get((name, centre), ([], []))\n    flat = \' \'.join(text.split())\n    for w in must:\n        if w not in flat:\n            findings.append((\'FALSE OR MISSING WORDS\', \'%s: lacks "%s"\' % (tag, w)))\n    for w in mustnot:\n        if w in flat:\n            findings.append((\'FALSE OR MISSING WORDS\', \'%s: says "%s"\' % (tag, w)))\n\n    # The sky position: JPL\'s fetched figure, or plain words; never a typed value.\n    note = [ln for ln in lines if ln.strip().startswith(\'(apparent\')]\n    if not note:\n        findings.append((\'LINE DROPPED\', \'%s: no sky-position note\' % tag))\n    else:\n        counts[\'lines\'] += 1\n        if od.get(\'ra_3sigma\') is None:\n            if any(\'+/-\' in n for n in note) or not all(\'Horizons gives no uncertainty with it\' in n for n in note):\n                findings.append((\'TYPED SKY VALUE\', \'%s: %s\' % (tag, note[0].strip())))\n        elif not all(\'JPL Horizons 3-sigma\' in n for n in note):\n            findings.append((\'WRONG SKY NOTE\', \'%s: %s\' % (tag, note[0].strip())))\n        if not all(\'as seen from Earth\' in n for n in note):\n            findings.append((\'WRONG SKY NOTE\', \'%s: does not say "as seen from Earth"\' % tag))\n\n\ndef scan_sources(findings, sky_source=None, orrery_source=None):\n    """The typed table must not be back in the code, and fetch_position must\n    still make the 2xr call for small bodies and the hover callers stay three."""\n    if sky_source is None:\n        with open(os.path.join(HERE, \'celestial_coordinates.py\'), encoding=\'utf-8\') as f:\n            sky_source = f.read()\n    code = \'\\n\'.join(ln for ln in sky_source.split(\'\\n\') if not ln.lstrip().startswith(\'#\'))\n    if re.search(r\'MAJOR_BODY_UNCERTAINTIES\\s*(=|\\[)\', code) or \', typical"\' in code:\n        findings.append((\'TYPED SKY VALUE\', \'celestial_coordinates.py holds a typed \'\n                         \'uncertainty table or a "typical" fallback\'))\n    if orrery_source is None:\n        with open(os.path.join(HERE, \'palomas_orrery.py\'), encoding=\'utf-8\') as f:\n            orrery_source = f.read()\n    m = re.search(r\'\\ndef fetch_position\\(.*?\\n(?=def )\', orrery_source, re.S)\n    body = m.group(0) if m else \'\'\n    if \'fetch_small_body_state(\' not in body:\n        findings.append((\'DISPATCH\', \'fetch_position no longer fetches a small body \'\n                         \'with its 2xr uncertainty\'))\n    calls = len(re.findall(r\'=\\s*format_detailed_hover_text\\(\', orrery_source))\n    if calls != 3:\n        findings.append((\'DISPATCH\', \'palomas_orrery.py calls format_detailed_hover_text \'\n                         \'%d times, expected 3 (static plot, animation start, frames)\' % calls))\n\n\n# Horizons\' answer for 2P/Encke (record 90000091) from the Sun at JD\n# 2461325.5 with VEC_TABLE=\'2xr\' and OUT_UNITS=\'AU-D\', the header and the\n# data line as read 2026-10-12 through the chat\'s web-fetch tool.\nRECORDED_2XR_HEADER = (\n    \'            JDTDB,            Calendar Date (TDB),                      X,\'\n    \'                      Y,                      Z,                     VX,\'\n    \'                     VY,                     VZ,             X_s,\'\n    \'             Y_s,             Z_s,            VX_s,            VY_s,\'\n    \'            VZ_s,             R_s,             T_s,             N_s,\'\n    \'            VR_s,            VT_s,            VN_s,\')\nRECORDED_2XR_DATA = (\n    \'2461325.500000000, A.D. 2026-Oct-12 00:00:00.0000,  1.942725296484269E+00,\'\n    \'  5.522246602639908E-01,  2.704195947645857E-01, -1.203972263020625E-02,\'\n    \'  3.443839821663160E-03, -4.371888997361478E-04,  2.12131568E-06,\'\n    \'  7.25420125E-07,  4.93573275E-07,  1.24183900E-08,  2.35613571E-09,\'\n    \'  2.08273117E-09,  2.25639403E-06,  3.14493101E-07,  2.82151047E-07,\'\n    \'  1.18004525E-08,  4.59717385E-09,  1.92895507E-09,\')\nRECORDED_R_S_AU = 2.25639403E-06\nRECORDED_V_S_AU_D = (1.18004525E-08, 4.59717385E-09, 1.92895507E-09)\n\n\ndef _answer(header, data):\n    return (\'Target body name: 2P/Encke\\n\' + header + \'\\n$$SOE\\n\' + data\n            + \'\\n$$EOE\\n\')\n\n\ndef _swap_columns(header, data, a, b):\n    hs, ds = header.split(\',\'), data.split(\',\')\n    names = [h.strip() for h in hs]\n    i, j = names.index(a), names.index(b)\n    hs[i], hs[j] = hs[j], hs[i]\n    ds[i], ds[j] = ds[j], ds[i]\n    return \',\'.join(hs), \',\'.join(ds)\n\n\ndef check_2xr_reading(findings, counts):\n    """The 2xr answer is read by column name: the recorded answer, the same\n    answer with R_s and X_s swapped, and one whose R_s is "n.a."."""\n    want_km = 3 * RECORDED_R_S_AU * cn.KM_PER_AU\n    want_v = 3 * math.sqrt(sum(x * x for x in RECORDED_V_S_AU_D)) * cn.KM_PER_AU / DAY_S\n    cases = [(\'as recorded\', RECORDED_2XR_HEADER, RECORDED_2XR_DATA),\n             (\'R_s and X_s swapped\',) + _swap_columns(RECORDED_2XR_HEADER,\n                                                       RECORDED_2XR_DATA, \'R_s\', \'X_s\')]\n    for label, h, d in cases:\n        counts[\'answers\'] += 1\n        try:\n            row = pa.parse_vectors_2xr(_answer(h, d))[0]\n            rec = pa.uncertainty_record(row, \'90000091\', \'@10\', 2461325.5)\n        except Exception as ex:\n            findings.append((\'2XR READ BY POSITION\', \'%s: %s\' % (label, ex)))\n            continue\n        if (rec[\'range_3sigma_km\'] is None or abs(rec[\'range_3sigma_km\'] - want_km) > 1e-6 * want_km\n                or rec[\'speed_3sigma_km_s\'] is None\n                or abs(rec[\'speed_3sigma_km_s\'] - want_v) > 1e-6 * want_v):\n            findings.append((\'2XR READ BY POSITION\', \'%s: 3-sigma range %s km, speed %s km/s; \'\n                             \'expected %.1f km, %.3g km/s\' % (label, rec[\'range_3sigma_km\'],\n                                                              rec[\'speed_3sigma_km_s\'],\n                                                              want_km, want_v)))\n    counts[\'answers\'] += 1\n    names = [x.strip() for x in RECORDED_2XR_HEADER.split(\',\')]\n    toks = RECORDED_2XR_DATA.split(\',\')\n    toks[names.index(\'R_s\')] = \'  n.a.\'\n    try:\n        row = pa.parse_vectors_2xr(_answer(RECORDED_2XR_HEADER, \',\'.join(toks)))[0]\n        rec = pa.uncertainty_record(row, \'90000091\', \'@10\', 2461325.5)\n        od = _od(2.0108, 33.17)\n        od[\'position_uncertainty\'] = rec\n        acc = pa.resolve_accuracy(\'Encke\', \'Sun\', od, OBJECT_DEFINITIONS, parent_planets)\n        if acc[\'state\'] != \'none\':\n            findings.append((\'SMALL BODY WITHOUT SIGMA NOT IN THE NO-ERROR STATE\',\n                             \'Encke with R_s "n.a.": state %r\' % acc[\'state\']))\n    except Exception as ex:\n        findings.append((\'2XR READ BY POSITION\', \'R_s "n.a.": %s\' % ex))\n\n\nSYMMETRIC_PAIRS = [(\'Jupiter\', \'Mars\'), (\'Sun\', \'Jupiter\'), (\'Neptune\', \'EM-L1\'),\n                   (\'Io\', \'Earth\'), (\'EM-L1\', \'Uranus\')]\n\n\ndef check_symmetry(findings, counts):\n    """A from B and B from A are one distance with one error, so they must\n    print the same digits (neither side a small body, whose figure is\n    fetched for the body only)."""\n    for a, b in SYMMETRIC_PAIRS:\n        got = []\n        for name, centre in ((a, b), (b, a)):\n            lines = _hover(name, centre, _od(4.321, 10.0))\n            m = _find(lines, r\'Distance: ([-\\d,.]+) kilometers$\')\n            got.append(m.group(1) if m else None)\n        counts[\'pairs\'] += 1\n        if got[0] != got[1]:\n            findings.append((\'NOT SYMMETRIC\', \'%s from %s prints %s km, %s from %s prints %s km\'\n                             % (a, b, got[0], b, a, got[1])))\n\n\ndef _checker_small(entry, centre):\n    """The checker\'s own reading of which entries are JPL small bodies."""\n    if centre == \'Sun\' and \'helio_id\' in entry:\n        return True\n    oid, t = str(entry.get(\'id\', \'\')), entry.get(\'id_type\')\n    if t in (\'smallbody\', \'designation\', \'asteroid_name\', \'comet_name\') and not oid.startswith(\'-\'):\n        return True\n    return bool(re.match(r\'^9\\d{7}$\', oid))\n\n\ndef check_every_object(findings, counts):\n    """Every entry in the object list, from the Sun, Earth and Neptune,\n    with no fetched figure: a JPL small body must never be said to have no\n    stated accuracy, and nothing may print finer than whole kilometers."""\n    for o in OBJECT_DEFINITIONS:\n        if o.get(\'object_type\') in (\'exoplanet\', \'exo_host_star\', \'exo_binary_star\',\n                                    \'exo_barycenter\', \'fixed\'):\n            continue\n        for centre in (\'Sun\', \'Earth\', \'Neptune\'):\n            if o[\'name\'] == centre:\n                continue\n            small = _checker_small(o, centre) or (\n                \'helio_id\' in o and o.get(\'object_type\') != \'satellite\')\n            lines = _hover(o[\'name\'], centre, _od(7.0, 9.0))\n            counts[\'sweep\'] += 1\n            flat = \' \'.join(\' \'.join(lines).split())\n            if small and o.get(\'object_type\') != \'satellite\':\n                for w in (\'JPL states no accuracy for this position\',\n                          "JPL states no accuracy for %s\'s position" % o[\'name\']):\n                    if w in flat:\n                        findings.append((\'SMALL BODY SAID TO HAVE NO FIGURE\',\n                                         \'%s from %s says "%s"\' % (o[\'name\'], centre, w)))\n            m = _find(lines, r\'Distance: ([-\\d,.]+) kilometers$\')\n            if not m or \'.\' in m.group(1):\n                findings.append((\'FINER THAN THE FLOOR\', \'%s from %s: km line %s\'\n                                 % (o[\'name\'], centre, m.group(1) if m else \'missing\')))\n\n\ndef check_odd_inputs(findings, counts):\n    """A speed of \'N/A\' or not-a-number prints N/A with no speed sentence,\n    and a distance of zero does not divide by it."""\n    cases = [(\'Mercury\', \'Sun\', dict(_od(0.39, 47.0), velocity=\'N/A\')),\n             (\'Mercury\', \'Sun\', dict(_od(0.39, 47.0), velocity=float(\'nan\'))),\n             (\'Encke\', \'Sun\', dict(_od(0.0, 33.0), position_uncertainty={\n                 \'range_3sigma_km\': 1012.0, \'speed_3sigma_km_s\': None}))]\n    for name, centre, od in cases:\n        counts[\'odd\'] += 1\n        try:\n            lines = _hover(name, centre, od)\n        except Exception as ex:\n            findings.append((\'CRASH\', \'%s from %s, velocity %r: %s\'\n                             % (name, centre, od[\'velocity\'], ex)))\n            continue\n        if not isinstance(od[\'velocity\'], (int, float)) or od[\'velocity\'] != od[\'velocity\']:\n            if \'Velocity: N/A AU/day\' not in lines:\n                findings.append((\'WRONG SPEED DIGITS\', \'%s: speed not N/A\' % name))\n            if any(\'speed\' in ln for ln in lines if not ln.startswith(\'Velocity\')\n                   and \'Orbital\' not in ln):\n                findings.append((\'FALSE OR MISSING WORDS\', \'%s: a speed sentence with no speed\'\n                                 % name))\n\n\ndef run_checks(sky_source=None, orrery_source=None):\n    findings = []\n    counts = {\'hovers\': 0, \'lines\': 0, \'answers\': 0, \'pairs\': 0, \'sweep\': 0, \'odd\': 0}\n    for fx in FIXTURES:\n        judge_fixture(fx, findings, counts)\n    check_odd_inputs(findings, counts)\n    check_symmetry(findings, counts)\n    check_every_object(findings, counts)\n    check_2xr_reading(findings, counts)\n    scan_sources(findings, sky_source, orrery_source)\n    return findings, counts\n\n\n# ============================================================================\n# THE PLANTED FAULTS\n# ============================================================================\n\n@contextmanager\ndef _patched(module, attr, value):\n    old = getattr(module, attr)\n    setattr(module, attr, value)\n    try:\n        yield\n    finally:\n        setattr(module, attr, old)\n\n\n@contextmanager\ndef _row_finer():\n    rv = dict(pa.ROW_VALUES)\n    rv[\'DE430_JUPITER_SATURN_POSITION_PLACE_KM\'] = rv[\'DE430_JUPITER_SATURN_POSITION_PLACE_KM\'] / 10\n    with _patched(pa, \'ROW_VALUES\', rv):\n        yield\n\n\n@contextmanager\ndef _sigma_invented():\n    real = pa._side\n\n    def side(name, role, center_name, obj_data, objects, pp):\n        s = real(name, role, center_name, obj_data, objects, pp)\n        if s.get(\'reason\') == \'not_fetched\':\n            return {\'kind\': \'computed\', \'name\': name, \'err_km\': 1e-6,\n                    \'speed_err_km_s\': 1e-9, \'who\': name}\n        return s\n    with _patched(pa, \'_side\', side):\n        yield\n\n\n@contextmanager\ndef _floor_meters():\n    with _patched(pa, \'DISTANCE_FLOOR_EXPONENT_KM\', -3):\n        yield\n\n\n@contextmanager\ndef _line_dropped():\n    real = pa.distance_speed_lines\n\n    def lines(*a, **k):\n        return [ln for ln in real(*a, **k) if \'light-\' not in ln]\n    with _patched(pa, \'distance_speed_lines\', lines):\n        yield\n\n\n@contextmanager\ndef _typed_sky():\n    real = celestial_coordinates.get_precision_note\n\n    def note(obj_data, obj_name=None):\n        got = real(obj_data, obj_name)\n        return got if got else \'+/-0.005 arcsec\'\n    with _patched(celestial_coordinates, \'get_precision_note\', note):\n        yield\n\n\n@contextmanager\ndef _speed_finer():\n    real = pa.speed_error_km_s\n\n    def err(acc, distance_km, speed_km_s):\n        e, why = real(acc, distance_km, speed_km_s)\n        return e / 1000.0, why\n    with _patched(pa, \'speed_error_km_s\', err):\n        yield\n\n\n@contextmanager\ndef _read_by_position():\n    """A parser that reads the 2xr columns at their recorded positions."""\n    names = [x.strip() for x in RECORDED_2XR_HEADER.split(\',\')]\n    at = {n: i for i, n in enumerate(names)}\n\n    def parse(text):\n        lines = text.split(\'\\n\')\n        i = next(k for k, ln in enumerate(lines) if \'$$SOE\' in ln)\n        toks = lines[i + 1].split(\',\')\n        return [{n: pa._num(toks[at[n]]) for n in (\'X\', \'Y\', \'Z\', \'VX\', \'VY\', \'VZ\',\n                                                   \'R_s\', \'VR_s\', \'VT_s\', \'VN_s\')}]\n    with _patched(pa, \'parse_vectors_2xr\', parse):\n        yield\n\n\n@contextmanager\ndef _body_none_ignores_centre():\n    real = pa.resolve_accuracy\n\n    def resolve(name, centre, od, objects, pp):\n        acc = real(name, centre, od, objects, pp)\n        b = pa._side(name, \'body\', centre, od, objects, pp)\n        if b[\'kind\'] == \'none\' and acc[\'state\'] == \'floor\':\n            return {\'state\': \'none\', \'err_km\': None, \'reason\': b[\'reason\'], \'gap\': b[\'gap\']}\n        return acc\n    with _patched(pa, \'resolve_accuracy\', resolve):\n        yield\n\n\n@contextmanager\ndef _sheet_ignored():\n    with _patched(pa, \'SPACECRAFT_SHEET_ROWS\', {}):\n        yield\n\n\n@contextmanager\ndef _zero_sigma_kept():\n    def finite(x):\n        try:\n            return float(x)\n        except (TypeError, ValueError):\n            return None\n    with _patched(pa, \'_finite_positive\', finite):\n        yield\n\n\ndef _sky_source_with_table():\n    with open(os.path.join(HERE, \'celestial_coordinates.py\'), encoding=\'utf-8\') as f:\n        src = f.read()\n    return src + "\\nMAJOR_BODY_UNCERTAINTIES = {\'Mercury\': 0.005}\\n"\n\n\ndef _orrery_source_without_2xr():\n    with open(os.path.join(HERE, \'palomas_orrery.py\'), encoding=\'utf-8\') as f:\n        src = f.read()\n    return src.replace(\'fetch_small_body_state(\', \'fetch_small_body_state_REMOVED(\')\n\n\nPLANTS = [\n    ("Jupiter\'s row read ten times finer", _row_finer, {}, \'PLANET FINER THAN ITS ROW\'),\n    (\'a missing sigma turned into a tiny one\', _sigma_invented, {},\n     \'SMALL BODY WITHOUT SIGMA NOT IN THE NO-ERROR STATE\'),\n    (\'the kilometer floor moved to meters\', _floor_meters, {},\n     \'NO-ERROR BODY FINER THAN THE FLOOR\'),\n    (\'the light-time line left out\', _line_dropped, {}, \'LINE DROPPED\'),\n    (\'a typed sky value put back\', _typed_sky,\n     {\'sky_source\': \'table\'}, \'TYPED SKY VALUE\'),\n    ("the speed\'s error divided by a thousand", _speed_finer, {},\n     \'SPEED FINER THAN ITS DISTANCE\'),\n    ("fetch_position\'s 2xr call removed", None, {\'orrery_source\': \'no2xr\'}, \'DISPATCH\'),\n    (\'the 2xr columns read by position\', _read_by_position, {}, \'2XR READ BY POSITION\'),\n    ("a no-error body ignoring its centre\'s error", _body_none_ignores_centre, {},\n     \'NO-ERROR BODY IGNORES ITS CENTRE\'),\n    (\'a zero sigma taken as a figure\', _zero_sigma_kept, {}, \'ZERO SIGMA TAKEN AS A FIGURE\'),\n    ("the Voyagers\' data-sheet figures dropped", _sheet_ignored, {},\n     \'SPACECRAFT DATA-SHEET FIGURE IGNORED\'),\n]\n\n\ndef main():\n    problems = []\n    for label, ctx, sources, expected in PLANTS:\n        kw = {}\n        if sources.get(\'sky_source\') == \'table\':\n            kw[\'sky_source\'] = _sky_source_with_table()\n        if sources.get(\'orrery_source\') == \'no2xr\':\n            kw[\'orrery_source\'] = _orrery_source_without_2xr()\n        if ctx is None:\n            findings, _ = run_checks(**kw)\n        else:\n            with ctx():\n                findings, _ = run_checks(**kw)\n        hits = [d for c, d in findings if c == expected]\n        if hits:\n            print(\'planted: %-42s caught as %s (%s)\' % (label, expected, hits[0]))\n        else:\n            print(\'planted: %-42s NOT CAUGHT; findings: %s\'\n                  % (label, sorted(set(c for c, _ in findings)) or \'none\'))\n            problems.append(\'planted fault not caught: %s\' % label)\n\n    findings, counts = run_checks()\n    for cls, detail in findings:\n        print(\'FAIL: %s -- %s\' % (cls, detail))\n        problems.append(\'%s -- %s\' % (cls, detail))\n    rows = sorted(set(fx[4][1] for fx in FIXTURES if fx[4][0] == \'row\'))\n    sigmas = [\'%s from %s\' % (fx[0], fx[1]) for fx in FIXTURES if fx[4][0] == \'sigma\']\n    print(\'compared: every distance line (AU, kilometers, light time, surface) and \'\n          \'every speed line (AU/day, km/hr, km/sec), against errors worked out here from \'\n          \'%s; the fixture 3-sigma figures for %s; and the stated floors (whole kilometers, \'\n          \'one meter per second); plus the sky-position note, celestial_coordinates.py \'\n          \'and the dispatch in palomas_orrery.py\' % (\', \'.join(rows), \', \'.join(sigmas)))\n    print(\'examined: %s\' % \', \'.join(\n        \'%s from %s%s\' % (fx[0], fx[1], \' (its 2xr missing)\'\n                          if fx[2].get(\'position_uncertainty\', {}).get(\'missing\') else \'\')\n        for fx in FIXTURES))\n    if problems:\n        print(\'POSITION DIGITS: FAIL -- %d problem(s)\' % len(problems))\n        return 1\n    print(\'POSITION DIGITS: PASS -- %d of %d planted faults caught by name; %d hovers \'\n          \'examined, %d lines compared against their errors; %d pairs printed the same \'\n          \'from either end; %d hovers of every listed object from the Sun, Earth and \'\n          \'Neptune; %d recorded 2xr answers read by column name\'\n          % (len(PLANTS), len(PLANTS), counts[\'hovers\'], counts[\'lines\'], counts[\'pairs\'],\n             counts[\'sweep\'], counts[\'answers\']))\n    return 0\n\n\nif __name__ == \'__main__\':\n    sys.exit(main())\n',
    'documentation/HANDOFF_L401_distance_build1_20261012.md': '<!-- Doc-Kind: hand | Session record for build 1 of L-401 (the orrery\'s distance digits): the body hover printed by the errors JPL states, the speed with it, the typed sky-position table out, the checker and its planted faults, and Tony\'s look at five hovers. -->\n# Handoff: L-401 (the distance digits), build 1, the body hover\n\nBuilt on orrery 47815de273b30966769f7c679f889537dba994a5 at\nhttps://github.com/tonylquintanilla/palomas_orrery ("handoff L401") and\ngallery e3536c8732d7b62faa5c09515e4b7f1d1c10af9c at\nhttps://github.com/tonylquintanilla/tonyquintanilla.github.io, read, not\ntouched. Pushed at: Tony\'s commit after running the patch; the next\nsession reads it with `git ls-remote`.\nTony\'s local folders: orrery\n`C:\\Users\\tonyq\\OneDrive\\Desktop\\python_work\\palomas_orrery_for_github\\`;\ngallery `C:\\Users\\tonyq\\OneDrive\\Desktop\\python_work\\tonyquintanilla.github.io\\`.\nWritten October 12, 2026 with Anthropic\'s Claude Opus 5.5.\n\n- Type: BUILD, orrery only.\n- Brief: `documentation/HANDOFF_L401_distance_build1_brief_20261011.md`\n  (Fable 5.1, 2026-10-11). Design:\n  `documentation/DESIGN_L401_distance_digits_rulings_20261011.md`.\n- Patch: `patch_L401_3_body_hover_20261012.py`, saved in the orrery\n  folder. Move it to `documentation/` after the run.\n- Skills loaded, each matching the manifest: provenance-discipline\n  2.28, horizons-orbital-mechanics 1.2, orrery-coding-conventions 1.10,\n  safe-file-editing 1.13, agentic-pre-test 1.3,\n  ledger-and-session-records 1.20. The 1.20 obligation is discharged.\n\n## 1. Read this first\n\n- *The hover now prints each distance and speed to the digits JPL\'s\n  errors earn.* A planet by its published row; a small body by JPL\'s\n  own uncertainty for the date, fetched with its position; anything\n  else at whole kilometers with a sentence saying JPL states none.\n- *One message to Tony: the look (section 6).* His verdicts go in his\n  run record, one per line.\n- *The obligation that travels:* horizons-orbital-mechanics went to\n  1.3 in this patch; this session loaded 1.2. The next session confirms\n  its loaded copy reads 1.3 before Horizons work.\n\n## 2. What the patch does\n\nCode (verified in the sandbox, section 5):\n- `position_accuracy.py`, new. Works out the error for one body, one\n  centre and one date, in one place the hover reads, and builds the\n  hover\'s distance and speed lines from it. Also fetches a small body\'s\n  position with its 2xr uncertainty.\n- `visualization_utils.py`: `format_detailed_hover_text` prints its\n  distance and speed lines through `position_accuracy.py`. One\n  light-time line; the surface line only where the centre has a solid\n  surface; plain numbers.\n- `palomas_orrery.py`: `fetch_position` asks a small body\'s position\n  with `VEC_TABLE=\'2xr\'`, by a direct call, in place of astroquery\'s\n  call; no extra query. If it fails, the old call runs and the hover\n  says the uncertainty is not included.\n- `palomas_orrery_helpers.py`: `fetch_trajectory` marks a frame it\n  interpolated, or copied from another date; the animation\'s positions\n  worked out from elements are marked too (in `palomas_orrery.py`).\n- `celestial_coordinates.py`: `MAJOR_BODY_UNCERTAINTIES` and the\n  "typical" fallbacks are gone. The sky line says "as seen from Earth",\n  and that JPL gives no uncertainty where it gives none.\n- `orbital_period.py`: the false sentence "JPL lists no orbit\n  uncertainty for this body" now says why the Small-Body Database gave\n  no sigma, in true words.\n- `constants_new.py`: `DE430_MOON_POSITION_PLACE_KM` (the 2014 report\'s\n  abstract, "The present-day lunar orbit is known to submeter accuracy\n  through fitting lunar laser ranging data", read 2026-10-12) and\n  `S_PER_DAY` (NIST SP 811, Table 6, "1 d = 24 h = 86 400s", read\n  2026-10-12), and four Voyager rows, each spacecraft\'s predicted\n  pointing uncertainty in RA and DEC from its Horizons data sheet.\n  `constants_tokens.py`: the token `s_per_d`.\n- `test_position_digits.py`, new: the checker. In the maintenance run\n  as "Position digits (L-401)", with its dashboard button, "Test\n  Position Digits".\n\nRecords: the spacecraft survey\n(`documentation/SURVEY_L401_spacecraft_data_sheets_20261012.md`,\ncreated), the ledger (L-401, L-431, L-399, the header stamp), Tony\'s\npage by section, horizons-orbital-mechanics 1.3, the protocol v3.92\n(v3.89 moved to the history), this handoff.\n\nPermanent, after the script is archived: the two new modules, the two\nrows and the token, the checker and its button, the skill version.\n\n## 3. Method decided in the build (not Tony\'s; recorded so it is not re-asked)\n\n- **A body with no stated error, seen from a centre with one.** If the\n  centre\'s error is no larger than the kilometer floor, nothing that\n  prints changes, and the pair keeps the no-error state: a spacecraft\n  or a Lagrange point seen from Earth. If it is larger, it governs, by\n  the larger-of-two ruling: a Lagrange point seen from Neptune prints to\n  Neptune\'s 10,000 km place. The first draft kept none in both cases;\n  the review below found the second one wrong.\n- **An unstated error is not a large one** (Tony, 2026-10-12: "we know\n  spacecraft distance to fine precision because of signal travel time,\n  not to 10,000 km. actually, the precision of Neptune in that fly by\n  would have been increased due to knowing where Voyager was, not\n  Voyager\'s decreased."). "The true uncertainty may be larger" is said\n  only where JPL does give a figure that is not included here (a small\n  body\'s 2xr not fetched) or the position is not JPL\'s. A moon seen from\n  the Sun (Io): its orbit about Jupiter is fitted, not unknown.\n- **Then the Voyagers\' data sheets (Tony\'s ruling "A", 2026-10-12).**\n  Claude Fable 5.1 read the Voyager 2 sheet and found a stated figure;\n  Claude Opus 5.5 read both Voyager sheets and surveyed all 26\n  (`documentation/SURVEY_L401_spacecraft_data_sheets_20261012.md`).\n  JPL\'s Voyager positions are a 2022 refit of tracking that ended in\n  1992; each sheet states a predicted pointing uncertainty seen from\n  Earth, for 2030, as an angle (Voyager 1: 1.701 and 1.535 arcseconds;\n  Voyager 2: 4.718 and 3.715), and none for the distance. So the\n  Voyager 2 case above was wrong a second time: Voyager is the weak\n  part, by a lot. The hover now converts the larger angle at the\n  spacecraft\'s distance from Earth (about 210,000 km for Voyager 1 and\n  490,000 km for Voyager 2 today) and says the conversion is ours.\n  The distance from Earth comes from the sky-position query (quantity\n  20, astroquery\'s `delta`, same query). Where it was not fetched (the\n  animation) the hover says JPL\'s figure is not included. Recorded\n  rather than claimed: the angle is sideways to the line from Earth,\n  while the hover\'s distance runs almost along it; the two-way tracking\n  to 1992 constrained that direction better, but JPL gives no number,\n  so the sideways figure is the only scale, and rounding to it can err\n  only toward fewer digits. The 2030 figure is used for every date,\n  coarser than JPL knew near the encounters. The sheets\' 30-day re-read\n  goes on the Horizons check, by Tony\'s word, in its own session (L-395).\n- **The sky line\'s words narrowed:** "Horizons gives no uncertainty\n  with it", not "JPL gives none", since a data sheet can state one.\n- **Known limit, recorded:** the DE430 rows are today\'s accuracy,\n  applied to every date. Near a flyby the spacecraft\'s tracking tied\n  the planet to it (Voyager 2 at Neptune, 1989), so the true error of\n  that distance was far smaller, and the hover is coarser than JPL\n  knew: the safe direction, never finer. Using a spacecraft\'s tracking\n  near its encounters belongs with the encounter markers\' slice.\n- **The Sun adds nothing, on either side.** A planet\'s published\n  accuracy is that of its orbit about the Sun, so the Sun seen from\n  Earth is as well known as Earth seen from the Sun, and prints by\n  Earth\'s row. The design record\'s list of no-error cases names "the\n  Sun as a body"; read literally, the Sun seen from Jupiter would print\n  to whole kilometers, finer than Jupiter\'s own 100 km place. Seen from\n  a barycentre the Sun has no stated error, which is the case that list\n  covers. Raised here rather than settled silently.\n- **The local pairs.** A moon seen from its own planet, or a body seen\n  from its system\'s barycentre, has no stated error, except inside the\n  Earth and Moon system (the Moon, Earth, their barycentre), where\n  every distance is the Moon\'s orbit or a share of it, and the Moon\'s\n  row applies.\n- **What counts as a small body:** orbital_period\'s test by id_type,\n  plus any small-body record number (9 followed by seven digits)\n  whatever its id_type. From a centre other than the Sun, an entry\n  with a small-body `helio_id` is fetched by its system record, which\n  has no 2xr; its hover says JPL\'s figure is not included, not that\n  JPL states none.\n- **The words follow the figure that governs.** A floor case governed\n  by a small body\'s own figure keeps the computed words; the part with\n  no figure is named with the true reason (JPL states no accuracy, JPL\'s figure\n  is not included here, or no accuracy is stated). A speed set by the\n  one meter per second floor in a floor case says part of the speed has\n  no stated uncertainty. No speed sentence when there is no speed.\n- **Reading 1 uses the distance\'s printed precision.** "The same\n  relative precision as its distance" is taken as the error the\n  distance is printed by, the larger of its own and the whole-kilometer\n  floor. For the Moon seen from Earth the floor governs.\n- **A sigma of zero, or not a number, is no figure**, and lands in the\n  no-error state with "not included".\n- **Animation frames that are not JPL\'s for their date** state no\n  accuracy: the positions the animation works out from elements, and\n  the frames `fetch_trajectory` interpolates or copies from another\n  date (both now marked).\n- **The surface line** is left out for the Sun, Jupiter, Saturn,\n  Uranus, Neptune and Planet 9, and for a centre with no radius in\n  `CENTER_BODY_RADII` (it used to print the distance again with a\n  radius of 0).\n- **Unit conversions go through rows**, `S_PER_DAY` and `S_PER_HOUR`;\n  the light-hour test is light time over one hour, from\n  `SPEED_OF_LIGHT_KM_S`, with no typed 60.\n- **The display rules carry their rulings as sources**: the half-unit\n  (provenance-discipline 2.28), the 3-sigma level (the design record,\n  section 4), the two floors (the design record and the brief).\n\n## 4. Found, recorded and not chased (The Braid)\n\n- The animation\'s positions come from `fetch_trajectory`, which does\n  not ask for 2xr, so a small body\'s animation hover says its\n  uncertainty is not included. One class with the other slices; the\n  entries fetched by a system record from a centre other than the Sun\n  are the same class.\n- `orbital_period._is_small_body` reads id_type only, so C/2025_K1\n  (record 90004912, id_type \'id\') is not asked of the Small-Body\n  Database and its period line says the database "has no entry".\n  Recorded on L-431.\n- The RA and Dec themselves print to fixed widths\n  (`celestial_coordinates.extract_jpl_radec`). One class with the\n  sourced angular figure for a planet, kept for later.\n- `format_maybe_float` and `format_km_float` are unchanged. The hover\n  no longer calls them; their other callers are other slices\' sites.\n  `visualization_utils.py` still imports them; harmless, left.\n\n## 5. Tested (sandbox, which cannot reach JPL)\n\n- py_compile on every touched file; ASCII and LF on every file.\n- The headless run: the orrery\'s window opens under xvfb with no edit\n  to the copy.\n- Live dispatch, with JPL\'s answers stubbed from ones recorded\n  2026-10-12: the real `fetch_position` and `add_celestial_object` for\n  Mercury, Sedna and Encke from the Sun, Io from Jupiter, and Voyager\n  1. The hover was read back from the figure. Sedna and Encke each made\n  one 2xr query and no astroquery vector query. Sedna\'s 3-sigma came\n  out at 257,819.985 km, against quantity 39\'s 257,817.569 km.\n- A cold review by a separate Claude agent, which had not seen the\n  work being made, before delivery. It found, and this build fixed:\n  a no-error body ignoring a larger centre error (high); floor\n  sentences that called a computed figure "published", or said "JPL\n  states none" for a figure that was only not fetched; C/2025_K1 and\n  the system-record entries classed as having no stated error; a zero\n  sigma bringing back ten figures; a crash on a speed that is not a\n  number and a speed sentence with no speed; Earth from the Earth-Moon\n  barycentre; animation frames not from JPL carrying JPL\'s words. Each\n  is now a fixture, a sweep or a planted fault in the checker.\n- Tony\'s two corrections of 2026-10-12, before he ran the patch\n  (section 3): no "may be larger" for a part JPL simply states no\n  figure for; and, after Fable\'s reading, the Voyagers\' data-sheet\n  figures. The patch was rebuilt and replaced in the orrery folder\n  each time.\n- The checker: eleven planted faults, each caught by name (the brief\'s\n  six; the 2xr call removed from `fetch_position`; the 2xr columns\n  read by position; a no-error body ignoring its centre; a zero sigma\n  taken as a figure; the Voyagers\' data-sheet figures dropped). Then\n  23 hovers and 165 lines against errors it works out itself, the\n  Voyagers\' from the four rows by name; five pairs printing the same\n  from either end; every listed object hovered from the Sun, Earth and\n  Neptune (496 hovers); odd inputs; three recorded 2xr answers.\n- Maintenance run on a patched copy: 24 of 24, "0 TIER-1 -- the push\n  gate holds". Whole tree 288 Tier-1, against 292 before: the typed sky\n  table\'s four findings gone, none added.\n- The patch twice (the second refuses, nothing written) and on a\n  CRLF copy with notes of Tony\'s in the page and the ledger (matched,\n  written LF, said so, notes kept).\n\nNot tested here, and the patch\'s live check and Tony\'s look cover it:\nJPL\'s real answers, the real 2xr text on Tony\'s machine, and the\nwindow\'s hover.\n\n## 6. Tony\'s look, one message\n\n- Run `patch_L401_3_body_hover_20261012.py` from the orrery folder. At\n  its end it asks JPL for the five bodies at today\'s date, 00:00 UTC,\n  and prints each hover as the orrery will show it, and checks Sedna\'s\n  3-sigma against quantity 39.\n- Run `orrery_maintenance_run.py`: 24 of 24, and "0 TIER-1 -- the push\n  gate holds".\n- Open the orrery fresh (after the patch). Set the time to 00:00 to see\n  the same numbers. Plot Mercury, Sedna and Encke from the Sun, Io from\n  Jupiter, and Voyager 1, and hover each. Compare with the patch\'s\n  printout line by line.\n- What each should show:\n  - Mercury: kilometers to the whole kilometer, AU to eight decimals,\n    light-minutes; no surface line (the Sun has no solid surface);\n    "rounded to JPL\'s published accuracy for Mercury\'s orbit"; the speed\n    to the same relative precision, about six decimals in km/sec.\n  - Sedna: kilometers to the nearest million, AU to two\n    decimals, light-hours; "JPL\'s uncertainty for this position on this\n    date, at three standard deviations"; the speed by JPL\'s velocity\n    uncertainty, three decimals in km/sec.\n  - Encke: kilometers to the nearest thousand; the same sentences as\n    Sedna.\n  - Io from Jupiter: whole kilometers; no surface line; "JPL states no\n    accuracy for this position, so distances are shown to the whole\n    kilometer"; "JPL states no uncertainty for this body\'s speed".\n  - Voyager 1: kilometers to the nearest million (its sideways\n    figure, about 210,000 km, sets the place), AU to three\n    decimals, light-hours; "rounded to JPL\'s predicted sky-position\n    uncertainty for Voyager 1 in 2030, 1.701 arcseconds seen from\n    Earth", and that the conversion is ours; the speed to the same\n    relative precision.\n  - Every sky line says "as seen from Earth"; a planet\'s and Voyager\'s\n    say "Horizons gives no uncertainty with it"; Sedna\'s and Encke\'s\n    show JPL\'s figure.\n- His verdicts, in his run record, "-- correct" or "-- not clear" per\n  line: the no-error sentences; the Voyager sentence; the speed\n  sentences; the reworded period sentence; the sky line\'s words; the\n  light-time line; the surface line\'s presence or absence.\n- Then move the patch into `documentation/`, commit and push.\n\n## 7. Tony-actions\n\n- (do) Run the patch, then the maintenance run.\n- (do) Open the orrery fresh and hover the five bodies.\n- (decide) The words, line by line, in the run record.\n- (do) Move the patch into `documentation/`; commit and push.\n- (do) Reinstall horizons-orbital-mechanics 1.3 to the account\n  (Settings > Skills) from `skills/horizons-orbital-mechanics/SKILL.md`.\n\nSession record written October 2026 with Anthropic\'s Claude Opus 5.5.\n',
    'documentation/SURVEY_L401_spacecraft_data_sheets_20261012.md': '<!-- Doc-Kind: hand | Survey of the JPL Horizons data sheets of all 26 spacecraft the orrery draws, for L-401 (the distance digits): which state a trajectory uncertainty, in what form, and the revision date of each. Read 2026-10-12. -->\n# Survey: the spacecraft data sheets (L-401, the distance digits)\n\nBuilt on orrery 47815de273b30966769f7c679f889537dba994a5 at\nhttps://github.com/tonylquintanilla/palomas_orrery. The gallery is not\ntouched.\nTony\'s local folders: orrery\n`C:\\Users\\tonyq\\OneDrive\\Desktop\\python_work\\palomas_orrery_for_github\\`;\ngallery `C:\\Users\\tonyq\\OneDrive\\Desktop\\python_work\\tonyquintanilla.github.io\\`.\nWritten October 12, 2026 with Anthropic\'s Claude Opus 5.5.\n\n- Type: DISCOVERY (a list; it fixes nothing by itself).\n- Asked by Tony, 2026-10-12, with his ruling "A": a spacecraft\'s\n  distance is rounded by the uncertainty its own Horizons data sheet\n  states, converted at its distance from Earth and said to be ours.\n- Prompted by Claude Fable 5.1, which read the Voyager 2 sheet the same\n  day and found a stated figure the design had missed.\n- Method: each sheet fetched through the chat\'s web-fetch tool at\n  `https://ssd.jpl.nasa.gov/api/horizons.api?format=text&COMMAND=\'<id>\'&OBJ_DATA=\'YES\'&MAKE_EPHEM=\'NO\'`,\n  and asked for its revision date, the trajectory\'s source, the end of\n  tracking, and every statement of trajectory uncertainty with its\n  units. The tool reads through a small model, so each quote below is\n  as that model returned it; the Voyager figures were also read by\n  Fable through the browser pane.\n\n## 1. The answer\n\nOf the 26 spacecraft (27 entries; OSIRIS-REx and OSIRIS-APEX share\n-64), two sheets state a trajectory uncertainty: **Voyager 1 and\nVoyager 2.** Both state it as a predicted pointing angle seen from\nEarth, for 2030-Jan-1, with no sigma level and no distance uncertainty.\nThe other 24 state none.\n\nNot counted as trajectory uncertainties, though they look like them:\nCassini\'s "Pointing accuracy = 2.0 mrad" (the spacecraft\'s attitude\ncontrol); Gaia\'s "accuracy down to 24 uas" (its star measurements);\nJWST\'s "optical resolution: 0.1 arcseconds" (the telescope); New\nHorizons\' "2.3045(10)^6 km" (the sheet\'s way of writing 2.3045 x 10^6).\n\n## 2. Sheet by sheet\n\n| Spacecraft | Horizons id | Revised | Trajectory and tracking | Uncertainty stated |\n|---|---|---|---|---|\n| Voyager 1 | -31 | Aug 19, 2022 | 2022 refit by R. Jacobson; "no new tracking data possible since 1992" | "Formal predicted geocentric pointing uncertainty on 2030-Jan-1: RA +/- 1.701 arcseconds, DEC +/- 1.535 arcseconds" |\n| Voyager 2 | -32 | Aug 19, 2022 | 2022 refit by R. Jacobson of 1989-1992 tracking; none since 1992 | "RA +/- 4.718 arcseconds, DEC +/- 3.715 arcseconds", same sentence |\n| Apollo 11 S-IVB | -399110 | Mar 22, 2016 | reconstruction by D. R. Adamo, 2012 | none; "Uncertainties and errors in the extrapolated position prediction will increase" (no figure) |\n| Pioneer 10 | -23 | Jul 27, 2005 | JPL Navigation Team | none; "should be used cautiously for high precision" (no figure) |\n| Pioneer 11 | -24 | Jun 15, 2007 | JPL Navigation Team | none; same caution |\n| Galileo | -77 | Feb 23, 2008 | data fit 1989 to Aug 12, 2002 | none |\n| SOHO | -21 | Sep 01, 2026 | GSFC FDF | none; 1998 recovery gap "may be significant" (no figure) |\n| Cassini | -82 | Sep 28, 2018 | post-mission reconstruction | none (2.0 mrad is attitude control) |\n| Rosetta | -226 | Oct 24, 2016 | mission solutions | none |\n| New Horizons | -98 | Sep 01, 2026 | KinetX, tracking to 2026-Jul-20 | none |\n| Akatsuki | -5 | Aug 06, 2025 | ISAS/JAXA/JPL, fit to 2024-Apr-26 | none |\n| Juno | -61 | Sep 30, 2026 | JPL navigation; planning prediction after 2026-Sep-23 | none |\n| Gaia | -139479 | May 16, 2025 | ESOC, to 2025-Mar-28 | none (24 uas is the star survey) |\n| Hayabusa2 | -37 | Jun 30, 2026 | JAXA, fit to 2026-Jun-29 | none |\n| OSIRIS-REx / APEX | -64 | Sep 18, 2025 | reconstructed solutions | none; a "large jump at the 2026 merge" noted |\n| Parker Solar Probe | -96 | Sep 30, 2026 | fit to 2026-Sep-01 | none |\n| Mars 2020 (MarsRover) | -168 | Feb 18, 2021 | JPL navigation | none |\n| Lucy | -49 | Oct 25, 2025 | fit to 2025-Sep-08 | none |\n| DART | -135 | Mar 01, 2024 | final reconstruction | none |\n| JWST | -170 | Sep 21, 2026 | GSFC FDF, to Sep 20 | none (0.1 arcsec is the telescope) |\n| JUICE | -28 | Jun 30, 2026 | ESA, to June 16 | none |\n| Psyche | -255 | Sep 30, 2026 | JPL navigation, to August 11 | none |\n| Europa Clipper | -159 | Sep 30, 2026 | JPL navigation, to 2026-Sep-22 | none |\n| BepiColombo | -121 | Jun 30, 2026 | ESA, fit to 2026-Jun-14 | none |\n| Solar Orbiter | -144 | Sep 30, 2026 | ESA, fit to 2026-Sep-17 | none |\n| Artemis II | -1024 | Apr 20, 2026 | NASA/JSC | none |\n\n## 3. What the build does with it\n\n- Four rows in `constants_new.py`, `VOYAGER_1_POINTING_RA_2030_ARCSEC`\n  and its three siblings, each with its sheet as the source.\n- The hover converts the larger of RA and DEC at the spacecraft\'s\n  distance from Earth (fetched with the sky position, the same query)\n  and says, in words, that JPL states this angle for 2030 and none for\n  the distance, so the conversion is ours.\n- The other 24 keep whole kilometers with "JPL states no accuracy for\n  this position", which this survey shows is true of their sheets.\n- A sheet can change: twelve of these were revised in 2026. Tony,\n  2026-10-12: "agree. let\'s add it to the horizons check that runs\n  every 30 days i believe." Recorded on L-395 (the Horizons check), to\n  be built in its own session: on its 30-day cycle the check re-reads\n  each sheet and reports a moved "Revised:" date or a changed stated\n  uncertainty, for a person; it never edits a row.\n\nSurvey written October 2026 with Anthropic\'s Claude Opus 5.5.\n',
}

def live_check():
    """Ask JPL for the five bodies of Tony's look, through the code this
    patch wrote, and print each hover as the orrery will show it. Nothing
    is written. A failure here is printed, never fatal: the files are
    already in place."""
    import math
    import traceback
    from datetime import datetime, timezone
    sys.path.insert(0, ROOT)
    os.chdir(ROOT)
    try:
        from astropy.time import Time
        from astroquery.jplhorizons import Horizons
        import constants_new as cn
        from celestial_objects import OBJECT_DEFINITIONS
        from orbital_elements import parent_planets
        from visualization_utils import format_detailed_hover_text
        from position_accuracy import fetch_small_body_state, is_small_body_fetch
    except Exception as ex:
        print('LIVE CHECK could not start: %s' % ex)
        return
    now = datetime.now(timezone.utc)
    date = datetime(now.year, now.month, now.day)
    jd = Time([date]).jd.tolist()[0]
    entry = {o['name']: o for o in OBJECT_DEFINITIONS}
    look = [('Mercury', 'Sun'), ('Sedna', 'Sun'), ('Encke', 'Sun'),
            ('Io', 'Jupiter'), ('Voyager 1', 'Sun')]
    print()
    print('LIVE CHECK -- asking JPL for the five bodies of your look at %s UTC'
          % date.strftime('%Y-%m-%d %H:%M'))
    print('(the same queries fetch_position makes; set the orrery to this date')
    print(' and 00:00 to see the same numbers). Nothing is written.')
    for name, centre in look:
        print('-' * 70)
        try:
            o = entry[name]
            oid, itype = o['id'], o.get('id_type')
            if centre == 'Sun':
                cid = 'Sun'
            else:
                c = entry[centre]
                cid = c.get('center_id', c['id'])
            location = '@' + str(cid)
            unc = None
            if is_small_body_fetch(oid, itype):
                st, unc = fetch_small_body_state(oid, itype, location, jd)
                how = "one query, VEC_TABLE='2xr'"
            else:
                v = Horizons(id=oid, id_type=itype, location=location,
                             epochs=[jd]).vectors()
                st = {k: float(v[k][0]) for k in ('x', 'y', 'z', 'vx', 'vy', 'vz')}
                how = 'astroquery vectors, as before'
            od = dict(st)
            od['velocity'] = math.sqrt(st['vx'] ** 2 + st['vy'] ** 2 + st['vz'] ** 2)
            od['position_uncertainty'] = unc
            od['position_date'] = date
            od['object_type'] = o.get('object_type')
            try:
                e = Horizons(id=oid, id_type=itype, location='@399',
                             epochs=[jd]).ephemerides(quantities='1,2,20,36,37')
                cols = e.colnames
                od['ra'] = float(e['RA_app'][0] if 'RA_app' in cols else e['RA'][0])
                od['dec'] = float(e['DEC_app'][0] if 'DEC_app' in cols else e['DEC'][0])
                if 'delta' in cols:
                    od['earth_distance_au'] = float(e['delta'][0])
                for k, col in (('ra_3sigma', 'RA_3sigma'), ('dec_3sigma', 'DEC_3sigma')):
                    od[k] = None
                    if col in cols:
                        try:
                            val = e[col][0]
                            if val != 'n.a.' and val is not None:
                                od[k] = float(val)
                        except Exception:
                            od[k] = None
            except Exception as ex:
                print('  (sky position not fetched: %s)' % ex)
            full, _m, note = format_detailed_hover_text(
                od, name, centre, OBJECT_DEFINITIONS, {}, parent_planets,
                cn.CENTER_BODY_RADII, cn.KM_PER_AU, cn.LIGHT_MINUTES_PER_AU,
                cn.KNOWN_ORBITAL_PERIODS)
            print('%s from %s -- %s' % (name, centre, how))
            if unc:
                print('  JPL 3-sigma: distance %s km, speed %s km/s'
                      % (unc.get('range_3sigma_km'), unc.get('speed_3sigma_km_s')))
            for line in (full + (note or '')).split('<br>'):
                print('    ' + line)
        except Exception as ex:
            print('%s from %s -- FAILED: %s' % (name, centre, ex))
            traceback.print_exc()
    print('-' * 70)
    try:
        o = entry['Sedna']
        st, unc = fetch_small_body_state(o['id'], o.get('id_type'), '@Sun', jd)
        q = Horizons(id=o['id'], id_type=o.get('id_type'), location='500@10',
                     epochs=[jd]).ephemerides(quantities='39')
        q39 = float(q['r_3sigma'][0])
        mine = unc['range_3sigma_km']
        agree = abs(mine - q39) <= 0.001 * q39
        print("Sedna's 3-sigma distance: 3 x R_s = %.3f km; quantity 39 = %.3f km -- %s"
              % (mine, q39, 'agree' if agree else 'DISAGREE'))
    except Exception as ex:
        print("Sedna's quantity 39 cross-check could not run: %s" % ex)
    print('-' * 70)



def main():
    for f in CREATED:
        if os.path.exists(os.path.join(ROOT, f)):
            print('ERROR: %s already exists; this patch has run. NOTHING was written.' % f)
            return 1
    texts, crlf, done = {}, set(), []
    for f, label, old, new in EDITS:
        path = os.path.join(ROOT, f)
        if f not in texts:
            if not os.path.exists(path):
                print('ERROR: %s not found in %s. NOTHING was written.' % (f, ROOT))
                return 1
            raw = open(path, 'rb').read()
            if b'\r\n' in raw:
                crlf.add(f)
            texts[f] = raw.replace(b'\r\n', b'\n').decode('utf-8')
        t = texts[f]
        n = t.count(old)
        if n != 1:
            print('ANCHOR FAIL  %-45s %s (found %d times, expected 1). NOTHING was written.'
                  % (f, label, n))
            return 1
        if MARKER in t and t.index(old) > t.index(MARKER):
            print('ANCHOR FAIL  %-45s %s lies below the run-record marker. NOTHING was written.'
                  % (f, label))
            return 1
        texts[f] = t.replace(old, new)
        done.append((f, label))
    for f, t in texts.items():
        if any(ord(c) > 127 for c in t):
            pass  # a file may already hold non-ASCII this patch did not add
    for f, label, old, new in EDITS:
        if any(ord(c) > 127 for c in new):
            print('ERROR: an edit to %s would add non-ASCII. NOTHING was written.' % f)
            return 1
    for f, t in texts.items():
        with open(os.path.join(ROOT, f), 'w', encoding='utf-8', newline='') as h:
            h.write(t)
    for f, t in CREATED.items():
        with open(os.path.join(ROOT, f), 'w', encoding='utf-8', newline='') as h:
            h.write(t)
    for f, label in done:
        print('ok  %-45s %s' % (f, label))
    for f in CREATED:
        print('ok  %-45s created' % f)
    for f in sorted(crlf):
        print('note: %s was CRLF in the working copy; written LF' % f)
    print()
    print('patch applied (%d edits in %d files, %d files created)'
          % (len(done), len(texts), len(CREATED)))
    print('Stamps updated: the docstrings of every edited module, the ledger, the')
    print('protocol header and the skill\'s version line.')
    live_check()
    print()
    print('NEXT:')
    print('  1. Paste this output into your run record.')
    print('  2. Run orrery_maintenance_run.py: expect 24 of 24 and')
    print('     "0 TIER-1 -- the push gate holds".')
    print('  3. Open the orrery fresh; plot Mercury, Sedna and Encke from the Sun,')
    print('     Io from Jupiter, and Voyager 1; hover each; compare with the above.')
    print('  4. Your word on the words, per line, in the run record.')
    print('  5. Move this script into documentation/; commit and push.')
    print('  6. Reinstall horizons-orbital-mechanics 1.3 (Settings > Skills).')
    return 0


if __name__ == '__main__':
    sys.exit(main())
